"use strict";

const questions = [
  ["L1", "Robot autónomo", "Teoría", "E-1", "Un robot autónomo... (Selecciona una o más de una)", ["Consiste en un brazo articulado que mueve sus articulaciones de acuerdo con un programa informático", "Puede operar en entornos no totalmente conocidos", "Emplea información sensorial para tomar decisiones", "Realiza tareas repetitivas y preestablecidas"], [1, 2], "Un robot autónomo emplea información sensorial para tomar decisiones y puede operar en entornos no totalmente conocidos. Un brazo articulado que repite tareas preestablecidas describe un robot industrial tradicional."],
  ["L1", "Robot autónomo", "Teoría", "E-21", "Robot móvil vs. Robot industrial: ¿cuál es el emparejamiento correcto de estas 4 características?", ["Móvil: sin modelo del entorno totalmente conocido, construye modelo del entorno y cambia su posición; Industrial: movimientos precisos sin sensores extereoceptivos", "Industrial: sin modelo del entorno y cambia su posición; Móvil: movimientos preprogramados sin sensores extereoceptivos", "Ambos tienen siempre un modelo del entorno totalmente conocido de antemano", "Móvil: no usa sensores extereoceptivos; Industrial: necesita construir un mapa con SLAM"], 0, "En un robot móvil autónomo no existe un modelo del entorno totalmente conocido, debe construirlo/actualizarlo y cambia su posición en el entorno. En el robot industrial tradicional los movimientos son conocidos con gran precisión usando solo sensores propioceptivos (encoders internos), sin requerir sensores extereoceptivos."],
  ["L1", "Robot autónomo", "Teoría", "Nueva", "¿Cuál es la diferencia entre posición y pose de un robot plano?", ["La posición es (x, y); la pose añade orientación θ", "La posición incluye θ; la pose no", "La pose es siempre una trayectoria", "Son sinónimos"], 0, "Posición: dónde está el robot, (x, y). Pose: dónde está Y hacia dónde mira, (x, y, θ). La trayectoria describe cómo cambia su posición a lo largo del tiempo."],
  ["L1", "Locomoción", "Teoría", "Nueva", "Elegir ruedas en vez de patas influye en...", ["Solo en el aspecto exterior", "El modelo de movimiento, el terreno y los actuadores", "Solo en el nombre de los topics ROS", "La definición de probabilidad condicionada"], 1, "La locomoción determina cómo se mueve el robot, qué terrenos puede recorrer y qué actuadores y control necesita. El curso se centra sobre todo en robots terrestres de ruedas."],
  ["L1", "Paradigmas", "Teoría", "N-1", "¿Qué afirmaciones describen el paradigma deliberativo?", ["Sigue percibir → planificar → actuar", "Responde siempre antes que el reactivo", "Construye un modelo del entorno para planificar", "Conecta directamente sensores a motores sin plan"], [0, 2], "El deliberativo razona sobre un modelo y elabora un plan. Puede ser lento si el entorno cambia mientras planifica; conectar percepción directamente con acción es reactivo."],
  ["L1", "Paradigmas", "Teoría", "Nueva", "Hay que frenar inmediatamente ante un obstáculo inesperado. ¿Qué capa conviene que actúe primero?", ["Deliberativa: esperar un plan completo", "Reactiva: responder directamente a la lectura del sensor", "Cartográfica: rehacer el mapa a mano", "Ninguna: el robot nunca cambia el plan"], 1, "Una reacción local urgente no debería esperar un plan global. En un enfoque híbrido, la parte reactiva atiende el obstáculo y la deliberativa puede replantear la ruta después."],
  ["L1", "Paradigmas", "Teoría", "N-2", "¿Por qué suele elegirse una arquitectura híbrida?", ["Porque elimina la necesidad de sensores", "Porque usa solo planificación lenta", "Porque combina planificación global y reacción rápida", "Porque todas las acciones son preprogramadas"], 2, "Combina deliberación (objetivos y planes) con reacción (respuesta rápida a cambios). Es el enfoque principal del curso."],
  ["L1", "Problemas", "Teoría", "N-3", "La pregunta «¿dónde estoy?» incluye...", ["Localización y construcción de mapas/SLAM", "Evitar obstáculos y planificar rutas", "Planificación de tareas", "Calibración de actuadores únicamente"], 0, "Localización estima la pose en un mapa; mapping construye el mapa. SLAM aborda ambas cosas simultáneamente."],
  ["L1", "Problemas", "Teoría", "Nueva", "Relaciona «cómo llego de forma segura» con su tarea más directa.", ["Planificación de caminos y evitación de obstáculos", "Únicamente localización", "Planificación de tareas de alto nivel", "Solo crear el mapa"], 0, "Decidir por dónde ir es planificación de caminos; no chocar mientras se avanza es evitación de obstáculos. Saber dónde estoy es otro problema distinto."],
  ["L1", "Problemas", "Teoría", "Nueva", "Descomponer «entrega el paquete y después vuelve a cargar» en subobjetivos es...", ["Odometría", "Planificación de tareas", "Triangulación", "Control de ruedas"], 1, "Planificar tareas ordena objetivos, dependencias y acciones de la misión. La planificación de caminos resuelve cómo desplazarse entre lugares concretos."],
  ["L1", "Incertidumbre", "Teoría", "N-4", "¿Por qué se usa robótica probabilística?", ["Los sensores son ruidosos", "Las acciones no se ejecutan exactamente", "El entorno puede cambiar", "Siempre cuesta menos cálculo que un modelo determinista"], [0, 1, 2], "Modelos, sensores y acciones tienen incertidumbre. Las distribuciones permiten representarla, pero suelen exigir más cálculo y aproximaciones, no menos."],
  ["L1", "Embodiment", "Teoría", "T-1 (reconstruida)", "¿Qué significa embodiment (encarnación) en este contexto?", ["Que la IA solo funciona en humanoides", "Que el agente percibe y actúa físicamente en un entorno", "Que un robot no necesita sensores", "Que el programa está instalado en la nube"], 1, "La clave es la interacción sensoriomotora: el agente percibe el mundo y puede modificarlo con acciones. No exige cuerpo humanoide."],
  ["L1", "Arquitectura", "Teoría", "Nueva", "¿Qué conecta el núcleo cognitivo del robot con el mundo físico?", ["Sensores y actuadores", "Solo un planificador de tareas", "Una base de datos sin interfaces", "El número de grados de libertad"], 0, "Los sensores llevan información hacia el sistema (percibir); los actuadores ejecutan decisiones en el entorno (actuar)."],
  ["L1", "Alcance", "Teoría", "Nueva", "¿Qué distingue al robot industrial tradicional del móvil autónomo estudiado en la asignatura?", ["El industrial suele operar fijo en entorno estructurado y repetir movimientos", "El industrial nunca usa electricidad", "El móvil jamás usa programas", "El móvil no requiere percepción"], 0, "El industrial clásico es preciso y repetitivo en un entorno conocido; el móvil autónomo cambia de lugar y necesita percibir y decidir en entornos parcialmente desconocidos."],

  ["L2", "Arquitectura", "Teoría", "Nueva", "Una arquitectura de control sirve principalmente para...", ["Integrar percepción, decisiones y actuadores como sistema", "Definir solo el chasis", "Calcular únicamente una matriz de rotación", "Reemplazar al sistema operativo del ordenador"], 0, "La arquitectura coordina módulos que perciben, deciden y actúan; no es el hardware ni un cálculo aislado."],
  ["L2", "Propiedades", "Teoría", "Nueva", "Leer un LiDAR mientras se navega y se actualiza la localización ilustra...", ["Paralelismo", "Calibración", "Conmutatividad", "Cuantización"], 0, "Paralelismo es ejecutar tareas a la vez. No equivale a robustez: esta se refiere a afrontar fallos."],
  ["L2", "Propiedades", "Teoría", "Nueva", "Cambiar un parámetro o comportamiento sin parar el robot ilustra...", ["Flexibilidad en tiempo de ejecución", "Covarianza diagonal", "Sensor de solo rango", "Falta de modularidad"], 0, "Flexibilidad permite reconfigurarse en marcha. La modularidad, por su parte, facilita separar, probar y reutilizar piezas."],
  ["L2", "Propiedades", "Teoría", "N-6", "Si falla el sensor principal y el robot continúa con uno de reserva, la arquitectura muestra...", ["Paralelismo", "Solo velocidad", "Robustez", "Pérdida de módulos"], 2, "Robustez implica detectar/aislar fallos y recuperarse o degradar prestaciones de forma controlada. Tener componentes separados facilita hacerlo, pero la propiedad preguntada es robustez."],
  ["L2", "Propiedades", "Teoría", "Nueva", "Una interfaz que permite cambiar el localizador sin reescribir el navegador demuestra...", ["Modularidad", "Holonomía", "Resampling", "Independencia estadística"], 0, "Modularidad significa componentes con interfaces claras, encapsulados y reutilizables. El navegador consume la interfaz, no necesita saber cómo está implementado el localizador."],
  ["L2", "Propiedades", "Práctica", "Nueva", "Un sensor emite 100 mensajes/s. ¿Cada cuánto llega uno, idealmente?", ["Cada 100 ms", "Cada 10 ms", "Cada 1 ms", "Cada 1 s"], 1, "Paso 1: frecuencia f = 100 Hz significa 100 mensajes en 1 segundo. Paso 2: período T = 1/f = 1/100 s = 0,01 s. Paso 3: 0,01 s × 1000 = 10 ms. No confundas Hz (veces por segundo) con ms (tiempo entre veces)."],
  ["L2", "Paradigmas", "Teoría", "N-7 (adaptada)", "Shakey (1967) representa principalmente...", ["El paradigma deliberativo percibir–planificar–actuar", "El reactivo puro", "Un filtro de partículas", "Un nodo de ROS 2"], 0, "Shakey es el ejemplo clásico del modelo deliberativo. El reactivo se asocia en las notas a Arbib (1980), y el híbrido se extiende desde los 90."],
  ["L2", "Paradigmas", "Teoría", "Nueva", "En una arquitectura híbrida, ¿qué asignación de funciones encaja mejor?", ["Plan global deliberativo; respuesta local a obstáculos reactiva", "Toda la navegación es una lista fija", "Reacción lenta; plan instantáneo", "Sensores desconectados del control"], 0, "La capa deliberativa piensa objetivos a largo plazo; la reactiva atiende el entorno inmediato. La capa de ejecución conecta ambas."],
  ["L2", "Behavior Trees", "Práctica", "N-8", "Un Sequence recibe SUCCESS de A y FAILURE de B. ¿Se ejecuta C en ese tick?", ["Sí, siempre", "No: devuelve FAILURE al fallar B", "Sí, pero devuelve SUCCESS", "Solo si A devuelve RUNNING"], 1, "Paso 1: Sequence evalúa A; SUCCESS permite seguir. Paso 2: evalúa B; FAILURE detiene la secuencia inmediatamente. Paso 3: C no recibe tick y el resultado global es FAILURE."],
  ["L2", "Behavior Trees", "Práctica", "N-9", "En un Fallback, A devuelve FAILURE y B devuelve RUNNING. ¿Qué devuelve el nodo?", ["FAILURE", "SUCCESS", "RUNNING", "Vuelve a evaluar A en el mismo tick"], 2, "Paso 1: Fallback prueba A; si falla pasa al siguiente. Paso 2: B está en ejecución (RUNNING), así que el Fallback espera con RUNNING. C no se evalúa aún, si existiera."],
  ["L2", "Behavior Trees", "Teoría", "Nueva", "¿Qué devuelven las hojas de un árbol de comportamiento al recibir un tick?", ["SUCCESS, FAILURE o RUNNING", "Solo verdadero o falso", "Solo una velocidad", "Siempre SUCCESS"], 0, "Cada hoja (acción o condición) responde con uno de esos estados; RUNNING señala una acción todavía en curso. Los nodos de control combinan los resultados."],
  ["L2", "Behavior Trees", "Teoría", "Nueva", "¿Qué hace un decorador Inverter en un Behavior Tree?", ["Invierte SUCCESS y FAILURE de su hijo", "Reordena todos los nodos del árbol", "Cambia la pose global de signo", "Publica un topic"], 0, "Un decorador modifica el comportamiento/resultado de su hijo. Inverter cambia éxito por fallo y viceversa; no es una operación geométrica."],
  ["L2", "Behavior Trees", "Teoría", "Nueva", "En Nav2, una RecoveryNode permite...", ["Intentar recuperarse y reintentar tras un fallo", "Hacer todos los nodos idénticos", "Eliminar toda la planificación", "Invertir matrices de covarianza"], 0, "El árbol puede limpiar costmaps, girar o esperar, y reintentar navegación. Lo importante es comprender la lógica de recuperación, no memorizar cada constante del ejemplo."],
  ["L2", "ROS 2", "Teoría", "N-10", "¿Qué es propio de ROS 2 frente a ROS 1? Marca todas las correctas.", ["Comunicaciones basadas en DDS", "Un maestro central obligatorio", "Parámetros asociados a cada nodo", "Uso exclusivo de Python 2.7"], [0, 2], "ROS 2 descubre nodos sin maestro central mediante DDS y ofrece QoS. Cada nodo tiene sus parámetros; Python 2.7 corresponde a ROS 1 antiguo."],
  ["L2", "ROS 2", "Teoría", "Nueva", "¿Qué describe mejor ROS?", ["Un ecosistema de herramientas, bibliotecas e interfaces para robótica", "Un reemplazo completo de Linux", "Un robot físico concreto", "Un único algoritmo de SLAM"], 0, "ROS se llama Robot Operating System, pero no sustituye a un sistema operativo general: ayuda a organizar software robótico y la comunicación entre procesos."],
  ["L2", "Componentes", "Teoría", "Nueva", "¿Qué diferencia hay entre paquete, ejecutable y nodo?", ["El paquete organiza software; el ejecutable es un programa; el nodo es un componente ROS en ejecución", "Los tres son el mismo topic", "El nodo es siempre un fichero XML", "El paquete solo contiene sensores físicos"], 0, "Piensa: paquete = carpeta/unidad de distribución; ejecutable = programa que lanzas; nodo = componente ROS activo. Un ejecutable puede alojar varios nodos."],
  ["L2", "Componentes", "Teoría", "E-22", "Empareja cada componente de ROS (Nodo, Topic, Acción, Servicio, Paquete) con su definición exacta:", ["Nodo: instancia en ejecución que provee/consume info · Topic: publicación/suscripción · Servicio: solicita operación particular · Acción: solicita operación, comprueba su estado y la cancela · Paquete: colección de ficheros y ejecutables con un propósito específico", "Nodo: colección de ficheros · Topic: solicita operación · Servicio: comprueba estado y cancela · Acción: publicación/suscripción · Paquete: instancia en ejecución", "Nodo: publicación/suscripción · Topic: instancia en ejecución · Servicio y Acción: idénticos sin cancelación · Paquete: solo mensajes .msg", "Topic: solicita operación y la cancela · Servicio: publicación/suscripción continua · Acción: colección de ficheros"], 0, "Fíjate en la diferencia literal entre Servicio («Permite a un nodo solicitar una operación particular a otro nodo») y Acción («...además de comprobar su estado y cancelarla»). Nodo es la instancia en ejecución, Topic es publicación/suscripción y Paquete es la colección de ficheros y ejecutables."],
  ["L2", "Componentes", "Teoría", "E-23", "Indica cuál de las siguientes afirmaciones sobre los nodos en ROS 2 es FALSA:", ["En ejecución, son instancias de programas ROS 2", "Deben implementar una capacidad o funcionalidad concreta dentro de la arquitectura de control", "Pueden pertenecer a un número arbitrario de paquetes", "Pueden suscribirse y/o publicar en un número arbitrario de topics"], 2, "La afirmación FALSA es que «pueden pertenecer a un número arbitrario de paquetes»: cada nodo está definido dentro de UN único paquete (aunque un paquete sí puede contener varios nodos). Un nodo sí puede publicar y suscribirse a tantos topics como necesite."],
  ["L2", "Herramientas", "Teoría", "E-24", "La herramienta rviz se emplea para:", ["rviz no es un comando de ROS", "Analizar diversas variables internas de ROS", "Visualizar en un entorno 3D: mapas, datos sensoriales y otros topics de la arquitectura ROS", "Visualizar la lista de ROS topics con una interfaz más agradable"], 2, "RViz (ROS Visualization) es el visualizador 3D de ROS/ROS 2 para mostrar mapas (/map), escaneos láser (/laser_scan), árboles de transformaciones (/tf), pose del robot y otros topics."],
  ["L2", "Herramientas", "Práctica", "E-25", "En rqt_graph aparecen los nodos /keyboard_control → /cmd_vel → /stage_ros → (/odom, /laser_scan, /tf), /robot_state_publisher → /tf, /gmapping → /map y rviz. ¿Qué acción NO se podría realizar?", ["Mover al robot en su entorno", "Construir un mapa", "Mover el brazo del robot", "Visualizar distintos elementos como la posición del robot, las observaciones del láser, etc."], 2, "Con /keyboard_control publicando en /cmd_vel puedes mover la base del robot; con /gmapping recibiendo /laser_scan y /tf construyes el mapa (/map); con rviz visualizas posición y láser. Lo que NO se puede hacer es mover el brazo del robot porque ningún nodo publica comandos a ningún controlador de articulaciones del brazo."],
  ["L2", "Comunicación", "Teoría", "E-26", "En ROS 2, ¿qué tipo de mensaje se emplea para trabajar con comandos de velocidad?", ["nav_msgs/Path", "nav_msgs/Odometry", "geometry_msgs/Accel", "geometry_msgs/Vector3", "geometry_msgs/Twist"], 4, "Los comandos de velocidad (como los publicados en /cmd_vel) usan el tipo geometry_msgs/Twist (en ROS 2, geometry_msgs/msg/Twist), que agrupa dos vectores 3D: velocidad lineal (linear) y velocidad angular (angular)."],
  ["L2", "Comandos ROS", "Práctica", "E-27", "¿Qué comando ROS 2 ejecuta un nodo/ejecutable llamado navigation_node que se encuentra dentro del paquete navigation?", ["ros2 run navigation navigation_node", "ros2 run navigation_node navigation", "ros2 launch navigation navigation_node", "ros2 node run navigation navigation_node"], 0, "La sintaxis de ros2 run es siempre: ros2 run <nombre_paquete> <nombre_ejecutable>. Por tanto: ros2 run navigation navigation_node."],
  ["L2", "Componentes", "Teoría", "Nueva", "¿Qué archivo comparten los paquetes ROS 2 C++ y Python como manifiesto?", ["package.xml", "Twist.msg", "map.yaml siempre", "launch.py obligatoriamente"], 0, "package.xml declara nombre, dependencias y metadatos. Los paquetes C++ usan típicamente CMakeLists.txt y los Python setup.py; no confundas manifiesto con interfaz."],
  ["L2", "Comunicación", "Teoría", "N-11", "Enviar «ve a (3,2)», ver progreso y poder cancelar: ¿qué mecanismo usarías?", ["Topic", "Servicio", "Parámetro", "Acción"], 3, "Una acción está pensada para operaciones largas: objetivo, feedback, resultado y cancelación. Un servicio devuelve una respuesta puntual; un topic distribuye un flujo de datos."],
  ["L2", "Comunicación", "Teoría", "Nueva", "Un LiDAR publica lecturas continuamente a varios consumidores. ¿Qué se usa?", ["Topic", "Servicio", "Parámetro", "Acción"], 0, "Un topic permite publicación/suscripción asíncrona y varios consumidores. No necesitas esperar respuesta a cada barrido de láser."],
  ["L2", "Comunicación", "Teoría", "Nueva", "Crear una nueva tortuga y recibir el nombre creado en una sola respuesta es...", ["Un servicio", "Un topic de telemetría", "Una acción larga", "Un parámetro del mapa"], 0, "Es petición–respuesta: cliente solicita una operación y servidor responde una vez. No hace falta feedback periódico ni cancelación."],
  ["L2", "Comunicación", "Teoría", "Nueva", "Modificar la velocidad máxima de un nodo en ejecución, si el nodo lo admite, corresponde a...", ["Un parámetro", "Una acción", "Una imagen LiDAR", "La definición de un paquete"], 0, "El parámetro configura un nodo. En ROS 2 los parámetros pertenecen a cada nodo, y pueden consultarse o modificarse según sus restricciones."],
  ["L2", "Interfaces", "Teoría", "Nueva", "¿Qué combinación de archivos de interfaz es correcta?", [".msg = mensaje; .srv = petición/respuesta; .action = objetivo/resultado/feedback", ".srv = topic; .msg = nodo; .action = paquete", ".msg = compilador; .srv = mapa; .action = sensor", "Todo se describe con .msg"], 0, "Distingue comunicación de su definición: topic usa mensajes (.msg), servicio usa Request/Response (.srv), acción usa Goal/Result/Feedback (.action)."],
  ["L2", "Comandos ROS", "Práctica", "N-12", "¿Qué comando muestra los mensajes que circulan por un topic?", ["ros2 topic list", "ros2 topic echo /scanner1", "ros2 node list", "ros2 interface show /scanner1"], 1, "Paso 1: quieres VER VALORES, no enumerar nombres. Paso 2: la familia es ros2 topic. Paso 3: echo imprime los mensajes. list solo enumera; interface show enseña los campos del tipo, no las lecturas en tiempo real."],
  ["L2", "Comandos ROS", "Práctica", "Nueva", "Quieres medir si /scanner1 publica a 10 Hz. ¿Qué comando ejecutas?", ["ros2 topic hz /scanner1", "ros2 topic list /scanner1", "ros2 param set /scanner1", "ros2 run /scanner1"], 0, "hz significa frecuencia en mensajes/segundo. Si la simulación va cargada, el valor medido puede diferir del teórico definido por el período del sensor."],
  ["L2", "Comandos ROS", "Práctica", "Nueva", "Quieres ver quién publica /cmd_vel y su QoS. ¿Qué comando ayuda?", ["ros2 topic info /cmd_vel --verbose", "ros2 pkg create /cmd_vel", "ros2 topic pub /cmd_vel", "ros2 param dump /cmd_vel"], 0, "info --verbose muestra tipo, extremos publicadores/suscriptores y perfiles QoS. Es útil si hay dos controladores publicando órdenes simultáneamente."],
  ["L2", "Comandos ROS", "Práctica", "Nueva", "¿Qué pareja de comandos relaciona ejecutables y nodos en marcha?", ["ros2 run paquete ejecutable; ros2 node list", "ros2 node list paquete; colcon echo", "ros2 topic echo paquete; ros2 param run", "ros2 service call paquete; ros2 run topic"], 0, "ros2 run inicia el ejecutable de un paquete; ros2 node list enumera nodos activos. No son lo mismo: un ejecutable puede tener más de un nodo."],
  ["L2", "Colcon", "Práctica", "N-13", "En un workspace, ¿cómo compilas SOLO el paquete p1?", ["colcon build p1", "ros2 run p1 build", "colcon build --packages-select p1", "ros2 pkg create p1"], 2, "Sitúate en la raíz del workspace (donde está src/); ejecuta colcon build --packages-select p1. colcon build a secas compila el workspace completo. Después carga install/setup.bash para descubrir lo compilado."],
  ["L2", "Colcon", "Práctica", "Nueva", "Tras compilar tu paquete ROS 2 en una terminal nueva, ¿qué falta normalmente antes de ros2 run?", ["source install/setup.bash en esa terminal", "Eliminar src/", "Convertir los topics en servicios", "Cambiar la covarianza de la pose"], 0, "Compilar deja los ejecutables en install/. Cada terminal debe cargar el entorno (source) para conocer el paquete; antes también se carga el ROS 2 base si hace falta."],
  ["L2", "Colcon", "Teoría", "Nueva", "¿Qué directorios de colcon contienen, respectivamente, fuentes y ejecutables instalados?", ["src/ e install/", "build/ y log/", "log/ y src/", "install/ y src/"], 0, "src/ guarda código fuente; build/ intermedios de compilación; install/ resultados utilizables; log/ registros. El comando colcon build se lanza desde la raíz."],
  ["L2", "Turtlesim", "Práctica", "N-14", "¿Qué mensaje mueve la tortuga a través de /turtle1/cmd_vel?", ["geometry_msgs/msg/Twist", "std_msgs/msg/String", "nav_msgs/msg/Odometry", "sensor_msgs/msg/LaserScan"], 0, "Twist expresa velocidad lineal y angular. Para un robot terrestre normalmente linear.x es el avance en m/s y angular.z el giro en rad/s."],
  ["L2", "MVSim", "Teoría", "Nueva", "¿Cuál es la distinción correcta entre MVSim y RViz2?", ["MVSim simula el mundo y la dinámica; RViz2 visualiza los datos ROS publicados", "RViz2 contiene la verdad interna del mundo y MVSim solo gráficos", "Los dos son encoders", "RViz2 crea el firmware de las ruedas"], 0, "MVSim conoce el estado de simulación. RViz2 muestra lo que le llega mediante topics/TF: que falte un objeto en RViz2 no prueba que falte en MVSim."],
  ["L2", "MVSim", "Práctica", "Nueva", "En MVSim, sensor_period_sec = 0.10. ¿Cuál es la frecuencia teórica?", ["0,1 Hz", "1 Hz", "10 Hz", "100 Hz"], 2, "Paso 1: 0,10 s es el tiempo entre lecturas. Paso 2: frecuencia f = 1/T = 1/0,10 = 10 Hz. Paso 3: comprueba la frecuencia real con ros2 topic hz: la carga de simulación puede bajarla."],
  ["L2", "MVSim", "Teoría", "Nueva", "¿Cuál es la diferencia entre /odom y /base_pose_ground_truth?", ["/odom estima y puede derivar; ground_truth es la pose conocida por el simulador", "Son dos órdenes de velocidad", "/odom siempre es exacta", "ground_truth es una transformación estática"], 0, "La verdad de simulación sirve para evaluar estimaciones; /odom acumula error como una odometría real. Que ambos publiquen nav_msgs/msg/Odometry no los hace equivalentes."],
  ["L2", "MVSim", "Práctica", "Nueva", "Detienes con Ctrl+C el publicador de /cmd_vel. ¿Cómo mandas una parada INMEDIATA?", ["Publicas un Twist con linear.x = 0 y angular.z = 0", "Esperas que el último Twist signifique cero", "Eliminas package.xml", "Cambias el frame odom por map"], 0, "Ctrl+C solo deja de enviar mensajes; NO envía una orden de freno. Publica un Twist nulo; el watchdog puede parar más tarde si no llegan órdenes, pero no sustituye la parada explícita."],
  ["L2", "MVSim", "Teoría", "Nueva", "¿Qué representa map → odom → base_link → sensor en TF?", ["Una cadena de marcos para ubicar robot y sensores", "Una lista de temas del examen", "El orden de los canales A y B", "Cuatro distribuciones gaussianas"], 0, "map es un marco global, odom la referencia odométrica continua, base_link el cuerpo y los sensores tienen sus marcos. Componer transformaciones coloca las lecturas en un marco común."],
  ["L2", "MVSim", "Teoría", "Nueva", "Para que un publicador y suscriptor se comuniquen correctamente en ROS 2 importan...", ["Nombre de topic, tipo de mensaje y QoS compatible", "Solo que sus nodos compartan paquete", "Solo el color en RViz2", "Que uno use siempre un maestro central"], 0, "El descubrimiento del nombre por sí solo no basta: ambos extremos han de acordar tipo y políticas QoS compatibles. Un topic puede figurar sin publicadores efectivos."],
  ["L2", "MVSim", "Teoría", "Nueva", "Un LiDAR 2D, una IMU y una cámara RGB producen, respectivamente...", ["Distancias de un barrido, datos inerciales y una imagen", "Tres órdenes de motor", "Solo ángulos absolutos", "Un mapa de ocupación completo en cada caso"], 0, "LiDAR mide rangos con rayos; IMU mide aceleración y giro; cámara RGB imágenes. Son fuentes sensoriales distintas y no equivalen a una pose global exacta."],

  ["L3", "Cinemática", "Teoría", "N-15", "Un diferencial no es holonómico porque...", ["No puede tener coordenada θ", "No puede desplazarse lateralmente de forma instantánea", "No puede llegar a cualquier lugar realizando maniobras", "Tiene necesariamente tres motores"], 1, "Tiene pose (x, y, θ), pero solo dos controles independientes; de lado, instantáneamente, no puede ir. Sí puede alcanzar muchas poses maniobrando, como un coche al aparcar."],
  ["L3", "Cinemática", "Teoría", "E-6 (adaptada)", "¿Qué vehículo es holonómico en movimiento plano?", ["Bicicleta convencional", "Coche Ackermann", "Plataforma con ruedas omnidireccionales que se desplaza lateralmente", "Diferencial tipo Roomba"], 2, "Holonómico puede generar velocidad lateral sin tener que girar primero. Las ruedas omnidireccionales permiten ese movimiento; bicicleta, coche y diferencial no."],
  ["L3", "ICR", "Teoría", "N-16", "¿Dónde está el ICR de un vehículo con ruedas que gira sin deslizar?", ["En el centro de masas siempre", "En la intersección de los ejes prolongados de las ruedas", "Siempre en el punto medio entre ruedas", "En el origen del mundo"], 1, "ICR = centro instantáneo de rotación: todos los puntos del chasis giran alrededor de él en ese instante. Para rodar sin deslizamiento, las prolongaciones de los ejes de las ruedas deben cruzarse en un mismo punto."],
  ["L3", "ICR", "Teoría", "E-9 (adaptada)", "Las prolongaciones de los ejes de tres ruedas rígidas se cruzan en puntos DISTINTOS. ¿Qué implica?", ["No hay un ICR común: alguna rueda deslizará", "El ICR está exactamente en la rueda central", "Movimiento recto sin deslizamiento", "El vehículo pasa a ser holonómico"], 0, "Un chasis rígido tiene un único ICR y una sola velocidad angular de guiñada. Si los ejes exigen centros distintos a la vez, no pueden rodar todos sin deslizar. Ejes paralelos, en cambio, permiten ICR en el infinito (recta)."],
  ["L3", "ICR", "Teoría", "N-21", "En vᵢ = ω Rᵢ, la ω representa...", ["El giro de cada rueda alrededor de su eje", "La velocidad angular del CHASIS alrededor del ICR", "Un valor independiente por rueda", "La velocidad lineal del robot"], 1, "Una sola ω describe el giro del chasis rígido. La velocidad de giro propia de la rueda sería ωᵢ = vᵢ/rᵢ; no confundas ambas."],
  ["L3", "Cinemática", "Teoría", "N-22 (adaptada)", "¿Qué magnitudes se controlan directamente en un diferencial típico?", ["Velocidades de las dos ruedas", "Posición x y posición y del mundo", "Ángulo de dirección delantero y velocidad trasera", "La covarianza de la pose"], 0, "El diferencial tiene una rueda motriz a cada lado (más posible rueda loca). Ackermann usa velocidad y dirección de las ruedas delanteras. Los controles se pueden convertir en (v, ω)."],
  ["L3", "Cinemática", "Teoría", "E-35", "Un robot que se mueve con un sistema de conducción diferencial (differential drive)... (Selecciona una o más de una)", ["Tiene 3 grados de libertad para controlar su movimiento", "El control de movimiento se hace con la velocidad de dos ruedas motrices", "Puede moverse en cualquier dirección en el plano", "Sólo puede moverse siguiendo trayectorias instantáneas que son circulares"], [1, 3], "Un diferencial se controla mediante las velocidades de sus 2 ruedas motrices (tiene solo 2 grados de libertad de control, no 3, y no puede desplazarse lateralmente en cualquier dirección). Su movimiento instantáneo alrededor del ICR es siempre circular (incluyendo la línea recta como caso límite de radio infinito y el giro sobre sí mismo con R=0)."],
  ["L3", "Cinemática", "Teoría", "E-32", "¿Cuáles de las siguientes expresiones de la cinemática diferencial son INCORRECTAS? (Nota: puede ser una sola)", ["vᵣ = ω(R + l/2)", "vᵣ = v_P + ω(l/2)", "ω = (vᵣ − vₗ)/l", "v_P = (vᵣ − vₗ)/2"], 3, "La expresión INCORRECTA es v_P = (vᵣ − vₗ)/2, porque la velocidad lineal del punto central P es la SEMISUMA v_P = (vᵣ + vₗ)/2, no la semidiferencia. Las tres primeras son correctas: vᵣ = ω(R + l/2) = ωR + ω(l/2) = v_P + ω(l/2), y ω = (vᵣ − vₗ)/l."],
  ["L3", "Odometría", "Teoría", "E-31", "Para calcular la odometría de un vehículo a ruedas de cinemática diferencial se necesita:", ["Un único codificador (encoder) por vehículo", "Un codificador para cada una de las ruedas que tenga, tanto las motrices, como las ruedas locas (castor wheels)", "Un codificador para cada una de las ruedas motrices (controladas)", "Un codificador para todas las ruedas locas (castor wheels) que tenga"], 2, "En un robot diferencial la odometría se calcula a partir del giro de las dos ruedas motrices (izquierda y derecha): Δsᵣ y Δsₗ. Las ruedas locas (castor wheels) son libres de apoyo y no llevan encoders para la odometría diferencial."],
  ["L3", "Cinemática", "Teoría", "N-19", "Para que un diferencial avance girando a la DERECHA...", ["La rueda derecha va más deprisa", "La izquierda va más deprisa", "Las dos ruedas van igual", "Deben detenerse las dos"], 1, "La rueda exterior a la curva recorre más distancia: en un giro derecho es la izquierda. Entonces vᵣ − vₗ < 0 y ω < 0."],
  ["L3", "Cinemática", "Práctica", "N-17", "l = 0,4 m; vₗ = 0,3 m/s; vᵣ = 0,5 m/s. ¿(ω, v, R)?", ["(0,5 rad/s; 0,4 m/s; 0,8 m)", "(−0,5 rad/s; 0,4 m/s; −0,8 m)", "(0,5 rad/s; 0,2 m/s; 0,4 m)", "(2 rad/s; 0,4 m/s; 0,2 m)"], 0, "Paso 1: diferencia de ruedas 0,5 − 0,3 = 0,2 m/s. Paso 2: ω = diferencia/l = 0,2/0,4 = 0,5 rad/s. Paso 3: v = (0,5 + 0,3)/2 = 0,4 m/s. Paso 4: R = v/ω = 0,4/0,5 = 0,8 m. El signo positivo indica curva izquierda."],
  ["L3", "Cinemática", "Práctica", "Nueva", "Las ruedas tienen radio 0,1 m y giran a 2 rad/s (izq.) y 4 rad/s (dcha.); l = 0,4 m. ¿v y ω del chasis?", ["v = 0,3 m/s; ω = 0,5 rad/s", "v = 3 m/s; ω = 5 rad/s", "v = 0,2 m/s; ω = 1 rad/s", "v = 0,3 m/s; ω = −0,5 rad/s"], 0, "Paso 1: convierte velocidad angular de RUEDA en velocidad lineal: vₗ = rωₗ = 0,1×2 = 0,2 m/s; vᵣ = 0,1×4 = 0,4 m/s. Paso 2: v = (0,2+0,4)/2 = 0,3 m/s. Paso 3: ω del CHASIS = (0,4−0,2)/0,4 = 0,5 rad/s. Son dos ω diferentes: rueda y chasis."],
  ["L3", "Cinemática", "Teoría", "N-18", "Si vᵣ = −vₗ ≠ 0, ¿qué hace el robot?", ["Avanza recto", "Gira en su sitio: v = 0, R = 0", "Solo se desplaza lateralmente", "Queda inmóvil"], 1, "La media de velocidades es cero: v = (vᵣ+vₗ)/2 = 0. La diferencia no es cero, luego gira; ICR en el centro del eje."],
  ["L3", "Cinemática", "Teoría", "N-23", "Si ambas ruedas avanzan igual, ¿cuál es el incremento LOCAL tras Δt?", ["(vΔt, 0, 0)", "(0, vΔt, 0)", "No se puede calcular", "(vΔt, vΔt, 0)"], 0, "ω = (vᵣ−vₗ)/l = 0. Es el caso recto: avanza sobre el eje x LOCAL vΔt, no se desplaza a un lado ni gira. Evita dividir por ω=0 en la fórmula del arco."],
  ["L3", "Cinemática", "Práctica", "N-20", "v = 1 m/s, ω = π/2 rad/s y Δt = 1 s. ¿Incremento LOCAL aproximado?", ["(1, 0, 90°)", "(0,637, 0,637, 90°)", "(0,637, −0,637, 90°)", "(0, 1, 90°)"], 1, "Paso 1: giro Δθ = ωΔt = π/2 = 90°. Paso 2: radio R = v/ω = 2/π ≈ 0,637 m. Paso 3: Δx = R·sen(90°) = 0,637; Δy = R·(1−cos(90°)) = 0,637. El arco no acaba donde lo haría una línea recta de 1 m."],
  ["L3", "Cinemática", "Práctica", "Nueva", "Con v = 1 m/s, ω = −π/2 rad/s, Δt = 1 s, el incremento LOCAL es...", ["(0,637, −0,637, −90°)", "(0,637, 0,637, −90°)", "(−0,637, 0,637, 90°)", "(1, 0, −90°)"], 0, "Paso 1: Δθ = −π/2. Paso 2: R = 1/(−π/2) = −2/π. Paso 3: Δx = R·sen(−π/2) = +2/π. Paso 4: Δy = R·(1−cos(−π/2)) = −2/π. Un giro derecho deja Δy local negativa."],
  ["L3", "Poses", "Teoría", "Nueva", "¿Qué significa x₀₂ = x₀₁ ⊕ x₁₂?", ["Pose de 2 respecto a 0 obtenida pasando por 1", "Pose 0 multiplicada por 2", "Sumar solo coordenadas sin rotar", "Una covarianza 0×2"], 0, "En xₐᵦ el primer índice (a) es el marco DESDE el que miras; el segundo (b) es el marco observado. Ir 0→1 y luego 1→2 da 0→2. ⊕ compone poses, no suma componente a componente."],
  ["L3", "Poses", "Teoría", "E-7", "Dado el desplazamiento incremental Δxₜ = [Δxₜ, Δyₜ, Δθₜ]ᵀ entre t−1 y t, ¿cuál es la pose del robot en el instante t en el sistema de referencia del mundo (World)?", ["[xₜ₋₁ + Δxₜ cos θₜ₋₁ − Δyₜ sin θₜ₋₁,  yₜ₋₁ + Δxₜ sin θₜ₋₁ + Δyₜ cos θₜ₋₁,  θₜ₋₁ + Δθₜ]ᵀ", "[Δxₜ cos θₜ₋₁ − Δyₜ sin θₜ₋₁,  Δxₜ sin θₜ₋₁ + Δyₜ cos θₜ₋₁,  Δθₜ]ᵀ", "[xₜ₋₁ + Δxₜ cos θₜ₋₁,  yₜ₋₁ + Δyₜ sin θₜ₋₁,  θₜ₋₁ + Δθₜ]ᵀ", "[xₜ₋₁ cos θₜ₋₁,  yₜ₋₁ sin θₜ₋₁,  θₜ₋₁ + Δθₜ]ᵀ"], 0, "Es la fórmula de composición de poses xₜ = xₜ₋₁ ⊕ Δxₜ: primero se rota el incremento local (Δxₜ, Δyₜ) un ángulo θₜ₋₁ con la matriz de rotación 2D y luego se suma la posición global (xₜ₋₁, yₜ₋₁); finalmente los ángulos se suman."],
  ["L3", "Poses", "Teoría", "E-33", "Si un robot se desplaza de la pose p₁ a la pose p₂ mediante un incremento local Δp = [Δx, Δy, Δθ]ᵀ (es decir, p₂ = p₁ ⊕ Δp), ¿cuál es la pose de p₁ expresada en el sistema de referencia de p₂?", ["⊖Δp = [−Δx cos Δθ − Δy sin Δθ,  Δx sin Δθ − Δy cos Δθ,  −Δθ]ᵀ (también escrita p₁ ominus p₂ = ⊖p₂ ⊕ p₁)", "[−Δx, −Δy, −Δθ]ᵀ", "[Δx cos Δθ − Δy sin Δθ,  Δx sin Δθ + Δy cos Δθ,  −Δθ]ᵀ", "p₂ ⊕ p₁"], 0, "La pose de p₁ vista desde p₂ es la inversa del incremento p₁₂ = Δp, es decir, p₂₁ = ⊖Δp = ⊖p₂ ⊕ p₁. Invertir una pose requiere girar (−Δx, −Δy) con R(Δθ)ᵀ, lo que da [−Δx cos Δθ − Δy sin Δθ, Δx sin Δθ − Δy cos Δθ, −Δθ]ᵀ."],
  ["L3", "Movimiento", "Teoría", "E-34", "En relación al movimiento general de un robot desde una pose xₜ₋₁ a otra xₜ, con una velocidad uₜ = (vₜ, ωₜ)ᵀ, en la que se desplaza Δxₜ, ¿cuál de las siguientes expresiones es correcta?", ["xₜ = xₜ₋₁ ⊕ Δxₜ", "xₜ = xₜ₋₁ ⊕ uₜ", "Δxₜ = xₜ₋₁ ⊕ uₜ", "xₜ = xₜ₋₁ + Δxₜ"], 0, "La nueva pose se obtiene componiendo la pose anterior con el incremento de pose local: xₜ = xₜ₋₁ ⊕ Δxₜ. No se puede componer directamente xₜ₋₁ con uₜ=(vₜ,ωₜ)ᵀ porque tienen dimensiones y unidades distintas (pose 3D frente a velocidad 2D), ni sumar Δxₜ con «+» sin rotar al marco global."],
  ["L3", "Poses", "Práctica", "E-36", "Con initial_pose = [0, 0, 0]ᵀ y la sucesión de incrementos odométricos u₁ = [1, 0, π/2]ᵀ, u₂ = [−1, 0, 0]ᵀ y u₃ = [2, 0, π]ᵀ aplicados con robot.step(u), ¿cuál es la pose final (pf)?", ["pf = [1, −1]ᵀ y «mirando hacia arriba»", "pf = [0, 2]ᵀ y «mirando hacia abajo»", "Ninguna de las anteriores", "pf = [1, 1]ᵀ y «mirando hacia abajo»"], 3, "Paso 1: desde [0,0,0]ᵀ (mirando a +x), u₁=[1,0,π/2]ᵀ avanza 1 en +x y gira a π/2 → p₁=[1, 0, π/2]ᵀ (mirando hacia arriba, +y). Paso 2: mirando a +y, u₂=[−1,0,0]ᵀ retrocede 1 m en el eje local (+y), es decir, baja a y=−1 sin girar → p₂=[1, −1, π/2]ᵀ. Paso 3: aún mirando a +y, u₃=[2,0,π]ᵀ avanza 2 m hacia +y (llega a y=−1+2=1) y gira π rad → p₃=[1, 1, 3π/2]ᵀ ≡ [1, 1, −π/2]ᵀ, que es [1, 1]ᵀ «mirando hacia abajo»."],
  ["L3", "Poses", "Práctica", "E-7 / N-24 (adaptada)", "Pose global (1, 2, 90°), incremento LOCAL (3, 0, −90°). ¿Pose final?", ["(4, 2, 0°)", "(1, 5, 0°)", "(1, −1, 0°)", "(4, 2, 180°)"], 1, "Paso 1: θ inicial = 90°, así que el eje x local apunta hacia el +y global. Paso 2: rotar (3,0) da (0,3). Paso 3: sumar posición inicial (1,2) → (1,5). Paso 4: orientación 90°−90°=0°. ¡No sumes 3 a x global!"],
  ["L3", "Poses", "Práctica", "N-27", "Marco 1 en (3,4) con θ=90° respecto a 0; punto (1,0) en 1. ¿Punto en 0?", ["(4,4)", "(3,5)", "(2,4)", "(3,3)"], 1, "Paso 1: (1,0) local es 1 m hacia delante. Paso 2: a 90°, delante apunta a +y global, por tanto R₉₀(1,0)=(0,1). Paso 3: añade origen (3,4) → (3,5)."],
  ["L3", "Poses", "Práctica", "N-25", "Para x=(2,0,90°), ¿cuál es la pose inversa ⊖x?", ["(−2,0,−90°)", "(0,2,−90°)", "(0,−2,−90°)", "(−2,0,90°)"], 1, "Paso 1: invertir NO es solo negar x e y, porque cambias de ejes. Paso 2: R₉₀ᵀ(2,0)=(0,−2); al negarlo queda (0,2). Paso 3: el giro inverso es −90°. Comprueba: x ⊕ ⊖x = (0,0,0)."],
  ["L3", "Poses", "Práctica", "N-26", "x₁=(1,1,90°), x₂=(1,3,180°) globales. ¿Pose de 2 vista desde 1?", ["(0,2,90°)", "(2,0,90°)", "(−2,0,90°)", "(0,−2,90°)"], 1, "Paso 1: diferencia GLOBAL de posición: (1−1,3−1)=(0,2). Paso 2: girar al marco de 1 (−90°): ese desplazamiento es (2,0) LOCAL: 2 m hacia delante. Paso 3: diferencia angular 180°−90°=90°. Resultado (2,0,90°)."],
  ["L3", "Poses", "Teoría", "N-28", "¿Se pueden intercambiar A y B en A ⊕ B?", ["Sí, porque es una suma normal", "No, en general A ⊕ B ≠ B ⊕ A", "Sí, si hay ángulos", "Solo con matrices 3×3"], 1, "Componer significa realizar desplazamientos en marcos que dependen de la orientación previa: girar y luego avanzar no suele dejarte donde avanzar y luego girar. SE(2) no es conmutativo."],
  ["L3", "Poses", "Práctica", "T-8 / N-31 (adaptada)", "Para llegar de 0 a 3 pasando por 1 y 2, ¿qué producto es correcto?", ["⁰T₁ · ¹T₂ · ²T₃", "²T₃ · ¹T₂ · ⁰T₁", "⁰T₁ + ¹T₂ + ²T₃", "¹T₀ · ¹T₂ · ²T₃"], 0, "Paso 1: empieza en 0 y escribe ⁰T₁. Paso 2: sigue desde 1 con ¹T₂. Paso 3: desde 2 con ²T₃. Los índices interiores encajan 0→1→2→3 y el resultado es ⁰T₃. El orden de multiplicación importa."],
  ["L3", "Poses", "Práctica", "N-30 (adaptada)", "Si conoces x₁₂ (2 respecto a 1) y x₁₃ (3 respecto a 1), ¿cómo obtienes x₂₃?", ["(⊖x₁₂) ⊕ x₁₃", "x₁₂ ⊕ x₁₃", "x₁₃ + x₁₂", "(⊖x₁₃) ⊕ x₁₂"], 0, "Paso 1: quieres ir de 2 a 3. Paso 2: vuelve de 2 a 1 invirtiendo x₁₂: x₂₁ = ⊖x₁₂. Paso 3: avanza de 1 a 3 con x₁₃. Cadena 2→1→3: x₂₃ = (⊖x₁₂) ⊕ x₁₃. La última opción daría 3→2."],
  ["L3", "Poses", "Teoría", "N-33", "¿Para qué sirve la coordenada homogénea extra «1» en un punto plano?", ["Para juntar rotación y traslación en una matriz 3×3", "Para cambiar grados a radianes", "Para que ⊕ conmute", "Para añadir una tercera distancia física"], 0, "Con (x,y,1) puedes escribir T=[R t; 0 1]. El producto de matrices hace de rotación más traslación y permite encadenar transformaciones."],
  ["L3", "Poses", "Teoría", "N-29", "Si T=[R t; 0 1], su inversa es...", ["[Rᵀ −t; 0 1]", "[Rᵀ −Rᵀt; 0 1]", "[−R −t; 0 1]", "[R Rᵀt; 0 1]"], 1, "El giro inverso es Rᵀ; la traslación hay que expresarla EN LOS EJES nuevos antes de negarla: −Rᵀt. Negar solo t confunde marcos cuando hay rotación."],
  ["L3", "Poses", "Teoría", "N-32", "¿Qué cumple la composición de poses planas SE(2)?", ["Es asociativa", "Tiene identidad e inversas", "Es conmutativa siempre", "La composición da otra pose válida"], [0, 1, 3], "SE(2) es un grupo: clausura, asociatividad, identidad (0,0,0) e inversas. No es conmutativo: el orden de las operaciones importa."],
  ["L3", "Poses", "Teoría", "E-11 (adaptada)", "Una marca está en p_local respecto al robot cuya pose global es x. ¿Cómo obtienes su posición global?", ["Rotas p_local con la orientación de x y sumas la posición de x", "Sumas coordenadas directamente aunque x esté girado", "Inviertes la marca como si fuera una pose", "Restas la orientación de la marca"], 0, "Punto global = R(θ_robot)·p_local + posición_robot. Un punto tiene coordenadas, no orientación propia: invertir un punto como una pose no tiene sentido."],
  ["L3", "Movimiento", "Teoría", "T-9 (reconstruida)", "Sobre modelos deterministas: señala las verdaderas.", ["La entrada puede ser (v,ω) o un incremento de odometría", "Con velocidad, conviertes primero a incremento local", "El incremento local se suma sin girar siempre", "La nueva pose se compone con la anterior"], [0, 1, 3], "Velocidad tiene 2 componentes; odometría aporta Δx, Δy, Δθ (3). En ambos casos se compone la pose anterior con el incremento LOCAL; hay que rotar las traslaciones al marco global."],
  ["L3", "Movimiento", "Práctica", "N-36", "Pose (1,1,90°); v=0,5 m/s, ω=0, tiempo 2 s. ¿Nueva pose?", ["(2,1,90°)", "(1,2,90°)", "(1,2,0°)", "(2,2,90°)"], 1, "Paso 1: ω=0 → recta; distancia LOCAL = vΔt = 0,5×2 = 1 m en el eje x del robot. Paso 2: mirando a 90°, x local apunta hacia +y global. Paso 3: (1,1)+(0,1)=(1,2); el ángulo no cambia."],
  ["L3", "Movimiento", "Teoría", "N-43", "¿En qué se usa el modelo de velocidad?", ["Simulación", "Planificación y seguimiento de trayectorias", "Predicción de pose en un filtro", "Medición de landmarks por un sensor"], [0, 1, 2], "El modelo de movimiento predice adónde va el robot usando una entrada. Medir marcas es propio de un modelo de observación."],
  ["L3", "Movimiento", "Teoría", "N-44", "Una serie de comandos (v,ω) constantes a trozos forma una trayectoria de...", ["Únicamente rectas", "Arcos de curvatura constante y rectas", "Un solo círculo siempre", "Saltos laterales puros"], 1, "Cada intervalo de velocidad constante sigue un arco si ω≠0 o recta si ω=0. Se compone un intervalo tras otro, cambiando el ICR cuando cambia el comando."],
  ["L3", "Odometría", "Práctica", "N-37", "Odometría: (2,1,0°) → (3,2,90°). Estimación anterior: (0,0,90°). ¿Estimación nueva?", ["(1,1,180°)", "(−1,1,180°)", "(3,2,180°)", "(1,−1,180°)"], 1, "Paso 1: la odometría parte mirando 0°, así que su incremento LOCAL es (3−2,2−1,90−0)=(1,1,90°). Paso 2: compón con la ESTIMACIÓN, que mira 90°: R₉₀(1,1)=(−1,1). Paso 3: nueva posición (−1,1) y ángulo 90+90=180°. No uses (3,2) como pose global."],
  ["L3", "Odometría", "Teoría", "N-38", "¿Por qué se usan incrementos entre poses odométricas y no la última pose odométrica como verdad?", ["Porque es siempre cero", "Porque la referencia de odometría es propia y acumula deriva", "Porque el incremento tiene solo dos dimensiones", "Porque así desaparece todo error"], 1, "El módulo de odometría mantiene SU referencia y arrastra errores. Extraes el desplazamiento relativo entre dos lecturas y lo aplicas a la mejor estimación de pose disponible; ese incremento también tiene incertidumbre."],
  ["L3", "Odometría", "Teoría", "N-39", "Un encoder incremental de rueda...", ["Cuenta transiciones para medir ángulo girado", "Usa orden de A/B para sentido", "Conoce directamente la posición global del robot", "Puede tener canal I con un pulso por revolución"], [0, 1, 3], "Mide giro de la rueda, NO pose global. A/B dan cuentas y sentido; I referencia una revolución. Para obtener movimiento del robot hay que conocer radio, separación de ruedas y componer incrementos."],
  ["L3", "Odometría", "Práctica", "N-94", "A/B pasa de 00→10→11→01→00 y luego 00→01→11→10→00. ¿Qué pasó?", ["Aumentó solo la rapidez", "Cambió el sentido de giro", "Hubo un pulso del canal I", "La rueda dejó de girar"], 1, "Las dos secuencias recorren los mismos cuatro estados pero en orden inverso: cambió el sentido. La frecuencia de transiciones, no su orden, indica rapidez; el índice I es otro canal."],
  ["L3", "Odometría", "Práctica", "N-96", "Radio de rueda 5 cm; encoder 2000 cuentas/vuelta. ¿Avance por cuenta?", ["0,157 mm", "1,57 mm", "0,314 m", "0,025 mm"], 0, "Paso 1: radio en metros r=0,05 m. Paso 2: circunferencia = 2πr ≈ 0,314 m por vuelta. Paso 3: dividir 0,314/2000 ≈ 0,000157 m/cuenta. Paso 4: pasar a milímetros: 0,000157×1000 = 0,157 mm. Ojo con m y mm."],
  ["L3", "Odometría", "Práctica", "N-40", "Encoders: Δsᵣ=0,30 m; Δsₗ=0,10 m; l=0,4 m. ¿Δs, Δθ y radio?", ["(0,20 m; 0,50 rad; 0,40 m)", "(0,40 m; 0,50 rad; 0,80 m)", "(0,20 m; 1 rad; 0,20 m)", "(0,10 m; 0,50 rad; 0,20 m)"], 0, "Paso 1: avance del centro Δs=(0,30+0,10)/2=0,20 m. Paso 2: giro Δθ=(0,30−0,10)/0,4=0,50 rad. Paso 3: radio R=Δs/Δθ=0,20/0,50=0,40 m. Es el mismo cálculo que con velocidades, sustituidas por distancias."],
  ["L3", "Odometría", "Práctica", "N-41", "Usando Δs=0,20 m, Δθ=0,50 rad, R=0,40 m, ¿incremento LOCAL aproximado?", ["(0,200; 0; 0,50)", "(0,192; 0,049; 0,50)", "(0,049; 0,192; 0,50)", "(0,192; −0,049; 0,50)"], 1, "Paso 1: sen(0,5 rad)≈0,4794 y cos(0,5 rad)≈0,8776. Paso 2: Δx=R·sen(Δθ)=0,4×0,4794≈0,192 m. Paso 3: Δy=R·(1−cos Δθ)=0,4×0,1224≈0,049 m. Paso 4: añade Δθ=0,50 rad. El giro es positivo, así que Δy también."],
  ["L3", "Odometría", "Práctica", "N-42", "El microcontrolador calcula a 100 Hz y navegación lee a 10 Hz. ¿Cuántos incrementos por lectura?", ["1", "10", "100", "1000"], 1, "Paso 1: hay 100 cálculos en 1 segundo. Paso 2: hay 10 lecturas en 1 segundo. Paso 3: 100/10=10 incrementos entre dos publicaciones. Equivalente: 100 ms / 10 ms = 10."],
  ["L3", "Odometría", "Teoría", "N-45 (adaptada)", "¿Cuál es un error SISTEMÁTICO que puede mitigarse calibrando?", ["Distancia entre ruedas mal medida", "Patinazo irregular sobre un charco", "Viento distinto en cada ejecución", "Cuantización aleatoria del encoder"], 0, "Sistemático = sesgo repetible, como l o radios de rueda erróneos: calibrar puede corregirlo. Aleatorio = cambia imprevisiblemente: se modela con incertidumbre."],
  ["L3", "Código de prácticas", "Práctica", "P-3 (adaptada)", "En next_pose(x,u,dt,cov), u=(v,ω). ¿Por qué hay un if ω==0?", ["Para evitar dividir por cero al calcular R=v/ω", "Porque el robot siempre gira", "Porque el encoder no da posición absoluta", "Para medir el sensor láser"], 0, "Paso 1: el caso curvo usa R=v/ω. Paso 2: si ω=0, dividir entre cero no está definido. Paso 3: toma el límite recto directamente: avance vΔt, desplazamiento lateral local 0 y giro 0. En código real conviene tratar también valores próximos a cero numéricamente."],
  ["L3", "Código de prácticas", "Práctica", "P-3 (adaptada)", "Si el ruido se añade al comando u=(v,ω), ¿qué dimensiones tiene su covarianza?", ["2×2", "3×3", "3×2", "1×3"], 0, "Paso 1: cuenta componentes de u: 2 (v y ω). Paso 2: la covarianza relaciona cada componente con cada componente → 2 filas y 2 columnas. La pose (x,y,θ) sí tiene covarianza 3×3, pero no es lo que se perturba aquí."],
  ["L3", "Código de prácticas", "Práctica", "N-48", "Incremento local: 2 m hacia delante y terminar orientado 90° a la DERECHA. ¿Qué compongo?", ["(2,0,+π/2)", "(2,0,−π/2)", "(0,2,−π/2)", "Sumo (2,0,−π/2) a la pose global sin rotar"], 1, "Paso 1: x local positivo es hacia delante → Δx=2, Δy=0. Paso 2: derecha es giro horario → Δθ=−90°=−π/2. Paso 3: pose nueva = pose ⊕ (2,0,−π/2), no suma de coordenadas globales."],
  ["L3", "Código de prácticas", "Práctica", "N-49", "inv_tcomp(toa,tob) rota (tob−toa) con R(θₐ)ᵀ. ¿Qué calcula?", ["La suma de poses globales", "La pose de b vista desde a: (⊖a) ⊕ b", "Solo la diferencia en ejes globales", "La pose inversa de b"], 1, "Primero resta posiciones globales; luego R(θₐ)ᵀ gira esa diferencia a los ejes de a. El ángulo relativo es θ_b−θ_a. Eso es exactamente la pose de b expresada desde a."],
  ["L3", "Probabilidad", "Teoría", "T-2 / N-65", "Para una variable continua con densidad positiva en x=2, ¿P(X=2)?", ["El valor numérico de la densidad en 2", "0", "1", "La desviación típica"], 1, "La densidad es altura, NO masa en un punto. La probabilidad es el ÁREA bajo la curva en un intervalo; un solo punto tiene anchura 0 y por tanto probabilidad 0."],
  ["L3", "Probabilidad", "Teoría", "N-64", "¿Qué propiedades tiene una pdf continua?", ["Nunca es negativa", "Su área total es 1", "Su altura jamás supera 1", "La probabilidad de un intervalo es el área sobre él"], [0, 1, 3], "La densidad puede superar 1 si se concentra en un intervalo estrecho. Lo que debe sumar 1 es su área total, no la altura máxima."],
  ["L3", "Probabilidad", "Teoría", "N-66", "La función de distribución acumulada F(x) es...", ["P(X=x)", "P(X≤x)", "La derivada de la densidad", "Siempre el mismo valor que p(x)"], 1, "F(x) acumula toda la probabilidad hasta x: F(x)=P(X≤x). La densidad p(x) es su derivada cuando existe, no la misma función."],
  ["L3", "Probabilidad", "Práctica", "N-67", "Si p(x,y)=0,12 y p(y)=0,4, ¿p(x|y)?", ["0,048", "0,3", "0,52", "3,33"], 1, "Paso 1: regla del producto p(x,y)=p(x|y)·p(y). Paso 2: despeja p(x|y)=p(x,y)/p(y). Paso 3: 0,12/0,4=0,3. Dividir, no multiplicar."],
  ["L3", "Probabilidad", "Práctica", "E-4", "P(celda)=1/8, independiente de orientación. P(S)=1/6 y P(E)=1/3. ¿P(celda y NO Norte ni Oeste)?", ["1/24", "1/16", "1/8", "1/2"], 1, "Paso 1: no Norte ni Oeste = Sur O Este. Son excluyentes: 1/6+1/3=1/2. Paso 2: ubicación y orientación son independientes: multiplicas P(celda)×P(S o E)=(1/8)×(1/2)=1/16. El número total de baldosas no interviene porque P(celda) ya está dado."],
  ["L3", "Probabilidad", "Práctica", "T-3 (reconstruida)", "P(celda fila 3, columna 4)=0,1 y P(columna 4)=0,3. ¿P(celda | columna 4)?", ["0,1", "1/3", "0,03", "3"], 1, "Paso 1: estar en esa celda implica estar en columna 4. Paso 2: probabilidad condicionada = P(celda y col4)/P(col4)=0,1/0,3=1/3. Restrínges el universo a la columna, no vuelves a multiplicar."],
  ["L3", "Probabilidad", "Práctica", "N-68", "P(hab.1)=0,75, P(hab.2)=0,25; P(puerta|hab.1)=0,2, P(puerta|hab.2)=0,6. ¿P(puerta)?", ["0,15", "0,30", "0,40", "0,80"], 1, "Paso 1: hay dos maneras excluyentes de detectar puerta. Paso 2: pondera cada habitación: 0,75×0,2=0,15 y 0,25×0,6=0,15. Paso 3: suma: 0,15+0,15=0,30. Esto es probabilidad total, no promedio sin pesos."],
  ["L3", "Probabilidad", "Teoría", "E-3 (corregida)", "Sin suponer independencia entre Y y Z, ¿cuál es la regla CORRECTA de probabilidad total condicionada?", ["p(x|y)=∫p(x|y,z)p(z|y) dz", "p(x|y)=∫p(x|y,z)p(z) dz siempre", "p(x|y)=p(x,y)·p(y)", "p(x|y)=∫p(x,y) dy"], 0, "En general necesitas ponderar con p(z|y): ya SABES y, por tanto cambia la distribución de z. En la autoevaluación histórica E-3 se marcó válida una versión con p(z); solo vale si Z e Y son independientes. Conviene aprender la regla rigurosa y reconocer esa salvedad."],
  ["L3", "Probabilidad", "Teoría", "Nueva", "¿Cómo se obtiene p(x) a partir de la densidad conjunta p(x,y)?", ["Integrando respecto de y", "Integrando respecto de x", "Multiplicando p(x,y) por p(y)", "Cambiando el signo de y"], 0, "Para quedarte con x, suma/integras TODAS las posibilidades de y: p(x)=∫p(x,y)dy. La variable eliminada es la de integración."],
  ["L3", "Probabilidad", "Teoría", "N-70", "Si X e Y son independientes CONDICIONADOS a Z...", ["p(x,y|z)=p(x|z)p(y|z)", "p(x|y,z)=p(x|z)", "Necesariamente también son independientes sin conocer Z", "Conocer Z puede explicar una dependencia aparente"], [0, 1, 3], "Tras fijar Z, saber Y no añade información sobre X. Eso NO implica independencia marginal: Z puede ser una causa común que relacione X e Y si se ignora."],
  ["L3", "Probabilidad", "Teoría", "N-71", "¿Qué dice la hipótesis de Markov aplicada al movimiento?", ["Basta pose anterior y comando actual para predecir la pose actual", "Solo importa la primera pose de la historia", "El mapa nunca cambia", "Todos los movimientos son independientes de la pose"], 0, "Si conoces xₜ₋₁ y uₜ, el pasado anterior no añade información sobre xₜ: p(xₜ | historia,uₜ)=p(xₜ | xₜ₋₁,uₜ)."],
  ["L3", "Gaussiana", "Teoría", "N-72", "¿Qué describe una gaussiana de pose (x,y,θ)?", ["Media de 3 elementos", "Covarianza 3×3 simétrica", "Varianzas negativas permitidas", "Covarianzas cruzadas fuera de la diagonal"], [0, 1, 3], "La media marca el centro; la diagonal de Σ son varianzas NO negativas; fuera de diagonal están relaciones entre componentes. Σ es simétrica."],
  ["L3", "Gaussiana", "Teoría", "T-4 / E-2 (adaptada)", "Una nube gaussiana 2D tiene elipses INCLINADAS. ¿Qué sugiere?", ["Covarianza cruzada distinta de cero (correlación)", "Covarianza esférica", "Variables necesariamente independientes", "Que p(x,y) siempre es cero"], 0, "La inclinación muestra relación lineal: cuando cambia x suele cambiar y. Una matriz diagonal produciría elipses alineadas con los ejes; para una gaussiana, diagonal implica independencia de sus componentes."],
  ["L3", "Gaussiana", "Teoría", "N-73", "Con Σ=diag(4,1), ¿cómo son las curvas de igual densidad en 2D?", ["Círculos", "Elipses alineadas, más anchas en x", "Elipses alineadas, más anchas en y", "Elipses inclinadas"], 1, "No hay covarianza cruzada → ejes alineados. Var(x)=4 frente a Var(y)=1 → desviaciones típicas 2 y 1, por tanto el eje x tiene doble escala."],
  ["L3", "Gaussiana", "Teoría", "N-74", "Si la covarianza cruzada σₓᵧ es NEGATIVA, la elipse tiende a...", ["Subir a la derecha", "Bajar a la derecha", "Ser un círculo forzosamente", "Tener varianzas negativas"], 1, "Correlación negativa: si x queda por encima de su media, y tiende a quedar por debajo de la suya. La nube se inclina hacia abajo a la derecha."],
  ["L3", "Gaussiana", "Práctica", "N-75 (adaptada)", "¿Cuál NO puede ser covarianza?", ["[[1,0],[0,2]]", "[[2,1],[1,2]]", "[[−1,0],[0,2]]", "[[1,0],[0,1]]"], 2, "Paso 1: las entradas diagonales son varianzas. Paso 2: una varianza es media de cuadrados y no puede ser negativa. Paso 3: la primera diagonal de la tercera matriz es −1: imposible. Además, una covarianza válida debe ser simétrica y semidefinida positiva."],
  ["L3", "Gaussiana", "Teoría", "N-91", "¿Por qué elegir muestras en vez de una sola gaussiana para una nube en forma de plátano?", ["Las muestras pueden representar formas no elípticas", "La gaussiana representa cualquier forma sin error", "Las muestras nunca necesitan memoria", "Porque cada muestra tiene idéntico ruido"], 0, "Una gaussiana queda resumida por media y covarianza y su nube típica es elíptica. Una colección de muestras puede seguir una curva, aunque requiere suficientes partículas."],
  ["L3", "Incertidumbre", "Teoría", "E-8", "¿Qué expresión es el modelo de movimiento PROBABILÍSTICO?", ["p(xₜ | xₜ₋₁, uₜ)", "p(uₜ | xₜ, xₜ₋₁)", "xₜ = xₜ₋₁ + uₜ exactamente", "p(xₜ | zₜ, m)"], 0, "Pregunta: «dadas la pose anterior y la orden, ¿qué poses finales son posibles?». Eso es p(xₜ | xₜ₋₁,uₜ). zₜ y mapa pertenecen al modelo de observación."],
  ["L3", "Incertidumbre", "Teoría", "N-90", "El modelo determinista y el probabilístico se diferencian en que...", ["El primero predice una pose exacta si la entrada es exacta", "El segundo describe una distribución de poses posibles", "El probabilístico solo admite velocidades", "La incertidumbre aleatoria se calibra y desaparece siempre"], [0, 1], "Un modelo determinista da un resultado concreto con entradas concretas; uno probabilístico describe resultados con ruido. Se pueden usar ambos con velocidad u odometría."],
  ["L3", "Incertidumbre", "Teoría", "N-81", "Sobre la velocidad ejecutada ũ=u+ξ, ξ~N(0,M), marca las correctas.", ["ξ tiene media 0 (no sesgado)", "M es 2×2 si u=(v,ω)", "Todas las ejecuciones acaban idénticas", "La pose final puede ser aleatoria"], [0, 1, 3], "El comando nominal es u; el ejecutado ũ cambia por ξ. Media cero significa que el ruido no favorece una dirección; M describe su dispersión en v y ω."],
  ["L3", "Incertidumbre", "Teoría", "N-97", "Si la posición inicial y el movimiento REAL ejecutado ũ son exactos en 1D, la posición final...", ["Sigue una gaussiana por definición", "Es xₜ=xₜ₋₁+ũ, determinista para ese ũ", "Es uniforme", "No depende del movimiento"], 1, "Fijados inicio y desplazamiento REAL, no queda incertidumbre: un solo resultado. Si el comando nominal u tiene ruido en su ejecución, entonces al considerar todos los posibles ũ aparece una distribución de poses (en 1D, gaussiana si el ruido lo es)."],
  ["L3", "Incertidumbre", "Práctica", "N-98", "Inicio exacto 3 m; orden 2 m; ruido gaussiano de media 0 y varianza 0,25 m². ¿Distribución final?", ["N(5; 0,25)", "N(5; 0,5)", "N(2; 0,25)", "Una delta en 5"], 0, "Paso 1: posición final = 3 + (2 + ruido) = 5 + ruido. Paso 2: media = 3+2+0=5 m. Paso 3: la posición inicial es exacta y añadir una constante NO cambia la varianza → 0,25 m². N(5;0,25) usa VARIANZA como segundo parámetro, no desviación típica."],
  ["L3", "Incertidumbre", "Práctica", "T-22 / N-76 (adaptada)", "X~N(5;0,5), U~N(2;0,3) independientes; Y=X+U. ¿Y? (segundo parámetro = varianza)", ["N(7;0,8)", "N(7;0,2)", "N(7;0,15)", "N(3;0,8)"], 0, "Paso 1: medias se suman: 5+2=7. Paso 2: para variables INDEPENDIENTES, varianzas se suman: 0,5+0,3=0,8. Paso 3: resultado N(7;0,8). No restes ni multipliques las varianzas."],
  ["L3", "Incertidumbre", "Práctica", "E-5 / N-77 (adaptada)", "A~N(3;4), Z=2A+1. ¿Media y varianza de Z?", ["(7;8)", "(7;16)", "(6;16)", "(7;9)"], 1, "Paso 1: media: 2·3+1=7. Paso 2: multiplicar por 2 multiplica VARIANZA por 2²=4: 4·4=16. Paso 3: sumar 1 solo desplaza el centro, no dispersa. Resultado N(7;16)."],
  ["L3", "Incertidumbre", "Práctica", "T-15 / N-78 (adaptada)", "A~N(0;1), B~N(0;2) independientes, Z=3A−2B. ¿Var(Z)?", ["1", "5", "13", "17"], 3, "Paso 1: cada factor se CUADRA al pasar a varianzas. Paso 2: 3²·Var(A)=9·1=9. Paso 3: (−2)²·Var(B)=4·2=8. Paso 4: suma por independencia: 9+8=17. El signo menos desaparece al cuadrar."],
  ["L3", "Incertidumbre", "Práctica", "N-79", "A~N(2;0,1), Z=A². Con linealización de primer orden, ¿media y varianza aproximadas?", ["(4;0,4)", "(4;1,6)", "(2;0,1)", "(4;0,01)"], 1, "Paso 1: evalúa f en la media: f(2)=2²=4. Paso 2: derivada f′(a)=2a; en a=2 vale 4. Paso 3: Var(Z)≈(f′(2))² Var(A)=4²×0,1=1,6. Es una APROXIMACIÓN de primer orden, no el resultado exacto de A²."],
  ["L3", "Incertidumbre", "Teoría", "N-82", "Si pose previa y comando son independientes, la covarianza predicha se escribe...", ["GΣₓGᵀ + VMVᵀ", "G + Σₓ + V + M", "Solo M aunque la pose anterior sea incierta", "GΣₓGᵀ − VMVᵀ"], 0, "Primer término: incertidumbre de la pose anterior propagada al resultado. Segundo: ruido del comando propagado al resultado. Se SUMAN bajo la hipótesis de independencia. Una covarianza no es una suma de jacobianos sueltos."],
  ["L3", "Incertidumbre", "Teoría", "N-80", "En el modelo de velocidad, ¿dimensiones de G, V y M si pose es 3D y entrada (v,ω) es 2D?", ["3×3; 3×2; 2×2", "3×3; 2×3; 3×3", "3×2; 3×3; 2×2", "2×2; 3×2; 3×3"], 0, "Regla de jacobianos: filas = dimensiones de SALIDA (pose: 3); columnas = dimensiones de ENTRADA. G deriva respecto a pose (3) → 3×3. V respecto a (v,ω) (2) → 3×2. M es covarianza del comando (2) → 2×2. V M Vᵀ da 3×3."],
  ["L3", "Incertidumbre", "Teoría", "N-83", "Si la pose anterior es EXACTA (Σₓ=0), ¿qué queda de la covarianza predicha por velocidad?", ["GΣₓGᵀ", "VMVᵀ", "M directamente, de tamaño 2×2", "Cero siempre"], 1, "Al poner Σₓ=0, el término de la pose previa desaparece. Queda VMVᵀ, ruido de entrada traducido al espacio 3D de la pose; puede ser distinto de cero."],
  ["L3", "Incertidumbre", "Práctica", "N-84", "Pose inicial exacta a 90°; covarianza del incremento local diag(0,04;0,01;0,02). ¿Covarianza global?", ["diag(0,04;0,01;0,02)", "diag(0,01;0,04;0,02)", "diag(0,02;0,01;0,04)", "Cero"], 1, "Paso 1: el marco local gira 90° respecto al global. Paso 2: incertidumbre de avance local (varianza 0,04 en x local) pasa al eje y global. Paso 3: varianza lateral local (0,01) pasa al eje x global. Paso 4: la angular 0,02 no cambia. Resultado diag(0,01;0,04;0,02)."],
  ["L3", "Incertidumbre", "Práctica", "N-99", "Media inicial (2,1,30°); incremento local Δx=1 m, Δy=0,2 m y Δθ=10°. ¿Media final?", ["(2,766;1,673;40°)", "(3;1,2;40°)", "(2,966;1,327;40°)", "(2,327;1,966;40°)"], 0, "Paso 1: cos30°≈0,866 y sen30°=0,5. Paso 2: x'=2+Δx·cos−Δy·sen=2+1·0,866−0,2·0,5=2,766. Paso 3: y'=1+Δx·sen+Δy·cos=1+0,5+0,173=1,673. Paso 4: θ'=30°+10°=40°. (3;1,2) sería suma sin rotación."],
  ["L3", "Incertidumbre", "Práctica", "N-100", "En el ejemplo anterior, ¿valores de (1,3) y (2,3) en el jacobiano respecto a la pose previa?", ["(−0,673;0,766)", "(0,673;−0,766)", "(−0,5;0,866)", "(−0,766;0,673)"], 0, "Paso 1: deriva x'=x+Δx cosθ−Δy senθ respecto a θ: −Δx senθ−Δy cosθ = −1·0,5−0,2·0,866 = −0,673. Paso 2: deriva y'=y+Δx senθ+Δy cosθ: Δx cosθ−Δy senθ = 1·0,866−0,2·0,5 = 0,766. Los ángulos de las derivadas se expresan en radianes."],
  ["L3", "Incertidumbre", "Práctica", "N-101", "Pose anterior exacta y θ=30°; ruido del incremento local diag(0,09;0,01;0,0027). ¿σ²ₓ, σ²ᵧ, σₓᵧ globales aprox.?", ["(0,070;0,030;+0,035)", "(0,09;0,01;0)", "(0,070;0,030;−0,035)", "(0,01;0,09;0)"], 0, "Paso 1: gira la covarianza local con R₃₀ Σ R₃₀ᵀ. Paso 2: Var(x)=0,09 cos²30°+0,01 sen²30°=0,0675+0,0025=0,070. Paso 3: Var(y)=0,09 sen²30°+0,01 cos²30°=0,0225+0,0075=0,030. Paso 4: Cov(x,y)=(0,09−0,01)sen30°cos30°≈0,08·0,433=+0,035. Rotar ruido anisótropo crea correlación global."],
  ["L3", "Muestras", "Práctica", "N-85", "Odometría (0,0,0°)→(1,1,90°). Descomposición giro–avance–giro: ¿θ₁,d,θ₂?", ["(45°,√2,45°)", "(90°,2,0°)", "(0°,√2,90°)", "(45°,2,90°)"], 0, "Paso 1: dirección del desplazamiento (1,1) = atan2(1,1)=45°. Orientación inicial 0° → primer giro θ₁=45°. Paso 2: distancia d=√(1²+1²)=√2. Paso 3: orientación final 90°; ya giraste 45°, resta θ₂=90−45=45°."],
  ["L3", "Muestras", "Teoría", "N-86", "Al aumentar sobre todo el ruido del primer giro θ₁, ¿cómo queda la nube de muestras odométricas?", ["Alargada solo en la dirección de avance", "Curvada en arco: un «plátano»", "Exactamente una única pose", "Necesariamente un círculo"], 1, "Si cada partícula arranca con un ángulo ligeramente distinto, al avanzar se abre en abanico/arco. El ruido solo en la DISTANCIA, por el contrario, estira las posiciones hacia delante y atrás."],
  ["L3", "Muestras", "Práctica", "N-87", "Partícula en (0,0,0); v=1 m/s, ω=0,5 rad/s, Δt=2 s. ¿Pose final aprox.?", ["(2;0;57,3°)", "(1,683;0,919;57,3°)", "(0,919;1,683;57,3°)", "(1,683;−0,919;57,3°)"], 1, "Paso 1: Δθ=ωΔt=0,5×2=1 rad≈57,3°. Paso 2: radio R=v/ω=1/0,5=2 m. Paso 3: Δx=2·sen(1 rad)≈1,683 m. Paso 4: Δy=2·(1−cos(1 rad))≈0,919 m. Sale del origen, así que pose final = incremento. La calculadora debe estar en radianes."],
  ["L3", "Muestras", "Práctica", "P-2 / N-88", "¿Cómo generar muestras N(media 3, VARIANZA 4) usando randn(n)~N(0,1)?", ["3 + 4*randn(n)", "3 + 2*randn(n)", "4 + 3*randn(n)", "randn(n)/4"], 1, "Paso 1: randn(n) tiene media 0, varianza 1. Paso 2: quieres varianza 4 → desviación típica √4=2. Paso 3: multiplica las muestras por 2: varianza resultante 2²=4. Paso 4: suma la media 3. No multiplicar por 4: daría varianza 16."],
  ["L3", "Probabilidad", "Práctica", "E-29 / T-6", "¿Cuál es la posición esperada (Expected Value) de un robot en un pasillo de 10 celdas (índices 1 a 10) con probabilidades [0, 0.2, 0.2, 0.1, 0.3, 0, 0.1, 0.1, 0.0, 0]?", ["4.1", "4.4", "Ninguna de las otras", "3.1"], 1, "Paso 1: el valor esperado es E[X] = ∑ i · P(X = i). Paso 2: multiplica cada celda no nula por su probabilidad: 2(0,2) + 3(0,2) + 4(0,1) + 5(0,3) + 7(0,1) + 8(0,1) = 0,4 + 0,6 + 0,4 + 1,5 + 0,7 + 0,8. Paso 3: suma todo → 4,4."],
  ["L3", "Gaussiana", "Teoría", "E-28", "La gráfica de elipses concéntricas en el plano (x₁, x₂) centradas en (μ₁, μ₂) representa:", ["La probabilidad conjunta (joint): p(x₁, x₂)", "La probabilidad condicionada: p(x₁ | x₂)", "La probabilidad condicionada: p(x₂ | x₁)", "Las probabilidades marginales: p(x₁), p(x₂)"], 0, "Las curvas de nivel (elipses de igual densidad) sobre el plano bidimensional (x₁, x₂) representan la distribución de probabilidad conjunta p(x₁, x₂). Las marginales p(x₁) y p(x₂) y las condicionadas para un valor fijo serían curvas 1D."],
  ["L3", "Gaussiana", "Teoría", "E-30", "Si a y b son dos variables aleatorias INDEPENDIENTES de distribución gaussiana, ¿cuáles de los gráficos de elipses son posibles para estas variables?", ["Solo aquellos cuyas elipses tienen sus ejes alineados con los ejes coordenados (incluyendo un círculo si σₐ = σᵦ)", "Los que tienen elipses inclinadas en diagonal a 45°", "Cualquier elipse con cualquier inclinación", "Ninguna elipse puede representar dos gaussianas independientes"], 0, "Para variables gaussianas, independencia equivale a covarianza cruzada nula (σₐᵦ = 0), es decir, matriz de covarianza diagonal. Geométricamente, eso significa que las elipses de nivel NO están rotadas/inclinadas: sus semiejes están alineados con los ejes horizontal y vertical (si además σₐ = σᵦ, la elipse es un círculo)."],
  ["L3", "Incertidumbre", "Teoría", "E-5", "Sea la variable aleatoria X ~ N(μ, Σ) y su transformación lineal Y = AX + B, siendo A una matriz y B un vector. Marca la respuesta correcta:", ["Y ~ N(Aμ + B,  AΣAᵀ)", "Y ~ N(Aμ + B,  AΣAᵀ + B)", "Y ~ N(Aμ,  AΣAᵀ)", "Y ~ N(Aμ + B,  AᵀΣA)"], 0, "En una transformación lineal Y = AX + B, la media se transforma linealmente como E[Y] = Aμ + B, y la covarianza se transforma cuadráticamente como Σ_Y = AΣAᵀ. El vector constante B solo traslada la media, no añade incertidumbre a la covarianza."],
  ["L3", "Incertidumbre", "Práctica", "E-37", "En el recorrido cuadrado (rojo = ideal, azul = real con ruido Σ = diag(σₓ², σᵧ², σ_θ²)), ¿cómo se distingue visualmente cada matriz de covarianza?", ["Σ = 0: azul coincide con rojo · Solo σₓ² > 0: tramos rectos más largos/cortos sin torcerse · Solo σᵧ² > 0: desplazamientos laterales manteniendo orientación · σ_θ² > 0: los giros se desvían y tuercen toda la ruta posterior", "Solo σ_θ² > 0 mantiene los ángulos rectos perfectos; solo σₓ² > 0 inclina la orientación del robot", "Todas las matrices diagonales producen exactamente la misma trayectoria azul", "Con Σ = 0 la trayectoria azul se desvía más que con σ_θ² > 0"], 0, "1) Si Σ = diag(0,0,0), no hay ruido y la ruta azul coincide con la roja. 2) Si solo hay varianza longitudinal (σₓ² > 0), el robot gira exactamente 90° pero avanza de más o de menos en cada lado. 3) Si solo hay varianza lateral (σᵧ² > 0), los triángulos azules mantienen la orientación correcta (paralelos a los ejes), pero se desplazan lateralmente. 4) Si hay varianza angular (σ_θ² > 0), la orientación del robot se tuerce y desvía todos los avances siguientes."],
  ["L3", "Muestras", "Teoría", "E-17", "La gráfica con elipses y nubes de puntos es el resultado de ejecutar comandos basados en odometría (forma analítica), tal y como se hizo en prácticas. ¿Cuál es el significado de los puntos que aparecen en la misma?", ["Representan la posición real del robot en todas las posibles simulaciones del movimiento", "Cada punto es una posible posición real del robot, fruto de componer una acción de control ruidosa con la posición real anterior", "Cada punto es una posible posición real del robot, fruto de componer una acción de control ruidosa con la posición ideal anterior", "Representan la posición ideal del robot"], 1, "Cada punto representa una posible posición real (una muestra/simulación Monte Carlo) obtenida al componer una acción de control ruidosa con la posición real (ruidosa) anterior de esa misma trayectoria. Por eso la dispersión de los puntos y las elipses crece paso a paso; si se compusiera con la posición ideal anterior, el error no se acumularía."],
  ["L3", "Muestras", "Teoría", "Nueva", "¿Qué cuatro combinaciones de modelo/representación estudia L3?", ["Velocidad u odometría × gaussiana o muestras", "Solo velocidad con muestras", "Solo odometría determinista", "Láser o cámara × GPS o TF"], 0, "Dos tipos de entrada (velocidad y odometría) por dos maneras de representar incertidumbre (media/covarianza o nube de muestras) = cuatro casos. La idea unificadora es propagar una pose incierta mediante movimiento incierto."],
  ["L3", "Muestras", "Práctica", "P-1 / N-89 (adaptada)", "La gráfica de una pdf N(μ,σ²) alcanza pico ≈0,2 en x=1. ¿μ y σ aproximados?", ["μ=1; σ≈2", "μ=1; σ≈0,2", "μ=0,2; σ=1", "μ=1; σ≈4"], 0, "Paso 1: una gaussiana simétrica alcanza el máximo en la media → μ=1. Paso 2: altura del pico = 1/(σ√(2π))≈0,399/σ. Paso 3: 0,399/σ≈0,2 → σ≈2. Ojo: la densidad puede ser 0,2, que no es una probabilidad puntual."],
  ["L3", "Muestras", "Teoría", "Nueva", "¿Qué significa que el ruido gaussiano de la entrada tenga media cero?", ["Que no introduce sesgo en promedio, aunque cada ejecución difiere", "Que nunca hay error", "Que su varianza es cero", "Que todas las ruedas giran en sentido contrario"], 0, "Error no sesgado = promedio de muchos errores ≈0, no ausencia de errores. Su dispersión sigue dada por la covarianza M."],
  ["L3", "Muestras", "Teoría", "Nueva", "Si el movimiento se ejecuta de forma ruidosa, la media predicha por primer orden se calcula...", ["Evaluando el modelo determinista en las medias", "Sumando las varianzas a cada coordenada", "Elegiendo la partícula más lejana", "Igualando siempre la pose a cero"], 0, "Primer orden: μₜ≈g(μₜ₋₁,uₜ). La incertidumbre se propaga aparte con jacobianos y covarianzas; no se añade como desplazamiento medio si el ruido es de media cero."],

  ["Extra", "Sensores", "Teoría", "E-10", "Para z=h(x,m)+w, w~N(0,Q), con x y m conocidos, ¿distribución de z?", ["N(h(x,m);Q)", "N(0;Q)", "N(h(x,m);Q⁻¹)", "No puede ser gaussiana"], 0, "h(x,m) es una constante si pose y mapa se fijan. Añadir ruido gaussiano de media 0 desplaza su media a h(x,m) y mantiene covarianza Q. Si la pose también fuese incierta, habría que propagarla por separado."],
  ["Extra", "Sensores", "Teoría", "E-19 / P-4", "Si zᵢ=√((mᵢ,x−x)²+(mᵢ,y−y)²) para cada landmark, ¿qué devuelve el sensor?", ["Solo rango: una distancia a cada marca", "Solo ángulo a una marca", "Pose global exacta", "Mapa de ocupación"], 0, "La raíz de suma de cuadrados es distancia euclídea. Con varias marcas, obtienes un vector de rangos: no calculas ángulos porque no aparece atan2."],
  ["Extra", "Sensores", "Teoría", "T-11 / N-52", "Una cámara monocular que solo ve la dirección a una marca corresponde al modelo...", ["Beam", "Likelihood field", "Range", "Bearing"], 3, "Bearing mide dirección/ángulo; range mide distancia. Beam y likelihood field suelen asociarse en el banco a barridos láser."],
  ["Extra", "Sensores", "Teoría", "T-12 / N-53", "Precisión GPS típica de más a menos: ¿qué orden aparece en el banco?", ["Stand Alone > DGPS > RTK", "RTK > DGPS > Stand Alone", "DGPS > RTK > Stand Alone", "RTK > Stand Alone > DGPS"], 1, "RTK es el más preciso (orden de centímetros), DGPS mejora el GPS normal mediante referencia, Stand Alone suele ser el menos preciso. Son valores orientativos del material, no garantías universales."],
  ["Extra", "Sensores", "Teoría", "T-13", "GPS se basa principalmente en mediciones...", ["Solo de distancia (pseudodistancia) a satélites", "De ángulos a satélites", "Solo de odometría de ruedas", "De rumbo relativo de cámara"], 0, "Las pseudodistancias a varios satélites permiten estimar la posición y corregir el sesgo del reloj. No se obtienen ángulos como medida GPS fundamental."],
  ["Extra", "Sensores", "Práctica", "E-18 / P-5", "Landmark 2D desde pose 3D: J_pose es 2×3, Σ_pose es 3×3; J_medida es 2×2, Σ_medida es 2×2. ¿Σ_landmark?", ["J_pose Σ_pose J_poseᵀ + J_medida Σ_medida J_medidaᵀ", "J_pose Σ_medida J_poseᵀ + J_medida Σ_pose J_medidaᵀ", "Σ_pose + Σ_medida sin jacobianos", "J_poseᵀ Σ_pose J_pose"], 0, "Paso 1: salida = posición 2D → covarianza final 2×2. Paso 2: el jacobiano de la POSE multiplica Σ_pose: (2×3)(3×3)(3×2)→2×2. Paso 3: el jacobiano de la MEDIDA multiplica Σ_medida: (2×2)(2×2)(2×2)→2×2. Paso 4: suma contribuciones si son independientes."],
  ["Extra", "Sensores", "Teoría", "T-16 / N-54", "Si apilas m medidas de rango y ángulo (2 valores cada una), ¿tamaño del jacobiano respecto a pose (x,y,θ)?", ["3×2m", "2m×3", "m×3", "2×3m"], 1, "Filas = número de SALIDAS: 2 por cada medida × m = 2m. Columnas = número de ENTRADAS de pose: 3. Por tanto 2m×3. Si fueran solo rangos, sería m×3."],
  ["Extra", "Sensores", "Teoría", "T-7", "¿Cuándo se factoriza p(z₁,...,zₖ | x,m) en el producto ∏p(zᵢ | x,m)?", ["Siempre", "Cuando las medidas son independientes condicionadas a pose y mapa", "Solo si los números medidos coinciden", "Cuando el robot no tiene mapa"], 1, "Condicionando en x y m, conocer una observación no cambia la distribución de otra. No es lo mismo que independencia sin condicionar, ni requiere que todas las observaciones sean idénticas."],
  ["Extra", "Localización", "Teoría", "E-12", "En p(zₜ|xₜ,m), durante la corrección con medida y mapa conocidos, ¿de qué variable se estudia la likelihood?", ["m", "xₜ", "zₜ", "Del tiempo Δt únicamente"], 1, "La medida zₜ ya se recibió y el mapa m se conoce. La función indica qué poses xₜ explican mejor esa medida; se evalúa como función de la pose."],
  ["Extra", "Localización", "Teoría", "E-13 / T-20", "En EKF, μ̄ₜ=g(uₜ,μₜ₋₁) y Σ̄ₜ=GΣGᵀ+R pertenecen a...", ["Predicción", "Corrección con sensor", "Remuestreo", "Asociación de datos"], 0, "La predicción utiliza el modelo de MOVIMIENTO y añade ruido R. La corrección usa las medidas: calcula K, innovación z−h(μ̄) y actualiza media y covarianza."],
  ["Extra", "Localización", "Teoría", "N-58", "En el EKF del banco, Rₜ y Qₜ representan, respectivamente...", ["Ruido de observación y de movimiento", "Ruido de movimiento y de observación", "Rotación y ganancia", "Dos matrices de identidad"], 1, "Rₜ aparece en predicción junto al movimiento; Qₜ aparece en la corrección como ruido del sensor. La letra R aquí NO es necesariamente la matriz de rotación geométrica."],
  ["Extra", "Localización", "Teoría", "E-15", "¿Qué es correcto sobre un filtro de partículas de localización?", ["Las partículas representan hipótesis de pose", "La observación ajusta sus pesos", "El movimiento únicamente pesa, sin mover partículas", "Puede mantener hipótesis múltiples"], [0, 1, 3], "Cada partícula es una posible pose; movimiento la desplaza, observación evalúa su plausibilidad y cambia su peso, remuestreo concentra recursos en hipótesis buenas. Puede ser multimodal."],
  ["Extra", "Localización", "Teoría", "T-19", "¿Por qué remuestrear partículas?", ["Para calcular el jacobiano", "Para combatir la degeneración, copiando las de mayor peso", "Para enviar Twist al robot", "Para hacer que el mapa se vuelva exacto"], 1, "Tras varias observaciones, pocas partículas pueden concentrar casi todo el peso. El remuestreo selecciona en proporción al peso y reemplaza otras; las nuevas suelen empezar con pesos iguales."],
  ["Extra", "Localización", "Teoría", "T-21 / N-60", "Un robot cree estar localizado, pero alguien lo desplaza sin avisar. ¿Caso?", ["Tracking normal", "Localización global conocida", "Robot secuestrado", "Solo odometría diferencial"], 2, "El robot se equivoca sobre su propia pose y no lo sabe. Si sabe que parte sin ninguna pose conocida, es localización global; si la pose aproximada es conocida, seguimiento."],
  ["Extra", "Localización", "Teoría", "T-14", "Decidir qué landmark del mapa corresponde a una observación se llama...", ["Calibración del motor", "Asociación de datos", "Marginalización", "Resampling"], 1, "Asociación de datos o correspondencia une medidas observadas con marcas del mapa. Una correspondencia equivocada puede empeorar gravemente la localización."],
  ["Extra", "Localización", "Teoría", "E-14 / N-62", "¿Qué falla si quieres minimizar mᵢ−(R xᵢ+t) DIRECTAMENTE, sin norma ni suma de cuadrados?", ["Es un vector, no una función escalar de error", "La rotación siempre es identidad", "No usa landmarks", "El mapa no puede tener puntos"], 0, "Un optimizador de mínimos cuadrados necesita un coste escalar, por ejemplo ||mᵢ−(Rxᵢ+t)||² (sumado para todas las marcas). El residuo sin norma es un vector, útil internamente pero no el coste final."],
  ["Extra", "Localización", "Teoría", "T-17 / T-23", "Mínimos cuadrados ponderados con error gaussiano equivalen a...", ["Máxima verosimilitud bajo esas hipótesis", "Siempre un filtro de partículas", "Un modelo sin observaciones", "Cualquier distribución de error sin más condiciones"], 0, "Para errores gaussianos, maximizar la likelihood equivale a minimizar la suma de residuos cuadrados ponderados por covarianza. Sin gaussianidad no hay tal equivalencia general."],
  ["Extra", "Localización", "Teoría", "E-20 (adaptada)", "Con SOLO distancias desde un punto del robot a landmarks, ¿se observa θ directamente en el modelo de rango puntual?", ["Sí, siempre con una sola marca", "No: la distancia depende de x,y, no de θ", "Sí, porque cualquier jacobiano debe ser 3×3", "La orientación se convierte automáticamente en rango"], 1, "En el modelo dᵢ=√((mᵢx−x)²+(mᵢy−y)²), θ no aparece: ∂dᵢ/∂θ=0. Varias marcas pueden precisar x,y, pero ese modelo de sensor por sí solo no determina θ."],
  ["Extra", "Localización", "Teoría", "T-18 (adaptada)", "Con un escaneo láser y mapa de puntos, pero sin datos de movimiento, ¿qué técnica local de ajuste encaja con el ejemplo del banco?", ["Odometría de ruedas", "Solo predicción sin medidas", "Alineamiento ICP / mínimos cuadrados", "Un encoder incremental como mapa"], 2, "Puedes ajustar geométricamente el escaneo al mapa con ICP/mínimos cuadrados. Esto NO significa que un filtro bayesiano jamás pueda actualizar con observaciones sin movimiento: esa generalización en la solución reconstruida sería demasiado fuerte."],
  ["Extra", "Localización", "Teoría", "E-20 / N-61 (adaptada)", "¿Por qué una buena pose inicial ayuda a Gauss–Newton en la localización?", ["Porque suele requerir menos iteraciones y reduce riesgo de mínimos locales", "Porque elimina el ruido de sensores", "Porque la odometría pasa a ser pose verdadera", "Porque elimina el mapa"], 0, "Gauss–Newton es iterativo y local: arranca cerca de la solución para converger más fácilmente. La odometría sirve como inicialización, aunque pueda tener deriva."],
  ["Extra", "Localización", "Teoría", "Nueva", "¿Qué distingue el paso de corrección del EKF del paso de predicción?", ["Corrección usa la innovación entre medida real y predicha", "Corrección solo mueve ruedas", "Predicción pesa partículas", "Predicción requiere descartar el mapa"], 0, "Tras predecir con movimiento, el EKF compara z real con h(μ̄) esperada. La diferencia (innovación) ajusta media y covarianza con la ganancia de Kalman."],
  ["Extra", "Sensores", "Práctica", "Nueva", "Para pasar una medida polar (r,a) a cartesiana, ¿cuál es el punto antes de llevarlo al mundo?", ["(r cos a, r sen a)", "(r+a, r−a)", "(cos r, sen r)", "(r sen a, −r cos a)"], 0, "Paso 1: r es longitud desde el sensor. Paso 2: proyecta sobre los ejes del sensor: x=r·cos(a), y=r·sen(a). Paso 3: para llevarlo al mundo, rota y traslada usando la pose del sensor/robot. No mezcles la medida polar con la posición global."],
  ["Extra", "Localización", "Teoría", "Nueva", "La creencia Bel(xₜ) tras predecir y observar se obtiene combinando...", ["Modelo de movimiento y likelihood de la observación", "Solo comandos sin pose anterior", "Solo una pose exacta constante", "Únicamente el color de las marcas"], 0, "La predicción integra posibles poses previas con el modelo de movimiento; la corrección multiplica por p(zₜ|xₜ,m), luego normaliza. Esa es la estructura del filtrado bayesiano."],
  ["L2", "Behavior Trees", "Práctica", "Nueva", "Fallback: A devuelve SUCCESS, B devolvería FAILURE. ¿Qué ocurre en ese tick?", ["B se evalúa y el Fallback falla", "B no se evalúa y el Fallback devuelve SUCCESS", "B se evalúa y se reintenta A", "El Fallback siempre devuelve RUNNING"], 1, "Paso 1: Fallback prueba A. Paso 2: SUCCESS significa que encontró una alternativa que funciona. Paso 3: se detiene inmediatamente, devuelve SUCCESS y B ni siquiera recibe tick. Es el comportamiento opuesto al Sequence, que sigue tras SUCCESS."],
  ["L2", "Componentes", "Práctica", "Nueva", "Para lanzar varios nodos juntos y asignar namespaces, ¿qué utilizarías?", ["Un archivo launch con ros2 launch", "Una pdf gaussiana", "Un único parámetro sin nodos", "ros2 topic echo"], 0, "Un launch agrupa programas, argumentos y espacios de nombres; puede ser Python, XML o YAML. Con ros2 launch paquete archivo arrancas lo configurado. Namespace prefija recursos para distinguir, por ejemplo, dos tortugas."],
  ["L2", "Colcon", "Práctica", "Nueva", "Para crear un paquete Python llamado control con la herramienta del curso, ¿qué bandera eliges?", ["--build-type ament_python", "--build-type ament_cmake si es Python", "--node-name como único argumento", "--packages-select sin ros2 pkg create"], 0, "Paso 1: ros2 pkg create crea el paquete dentro de src/. Paso 2: elige --build-type ament_python para Python (ament_cmake para C++). Paso 3: package.xml es el manifiesto común; setup.py registra ejecutables Python. Después compilas desde la raíz con colcon build."],
  ["L2", "MVSim", "Práctica", "Nueva", "En un teleoperador Python, ¿por qué usar spin_once(node, timeout_sec=0.0) en el bucle de teclado?", ["Atiende callbacks sin bloquear indefinidamente la lectura del teclado", "Convierte el robot en holonómico", "Sustituye a package.xml", "Asegura que la pose odométrica sea exacta"], 0, "Paso 1: tu programa debe leer teclas de forma continua. Paso 2: spin() bloqueante impediría volver al bucle de lectura mientras procesa callbacks. Paso 3: spin_once con espera nula atiende lo pendiente y devuelve el control. Al salir hay que publicar velocidad cero y restaurar el terminal."],
  ["L3", "Odometría", "Teoría", "T-10 (reconstruida)", "¿Qué puede causar un error de odometría? Marca todas las correctas.", ["Deslizamiento de ruedas", "Radio de rueda real distinto del usado en el cálculo", "Muestreo de encoders demasiado lento para el movimiento", "No conocer el mapa del edificio"], [0, 1, 2], "La odometría integra movimiento estimado de las ruedas: patinaje, parámetros mecánicos incorrectos o resolución/muestreo insuficiente la alteran. No usa el mapa, así que ignorarlo no constituye un error de odometría por sí solo."],
  ["L3", "Probabilidad", "Teoría", "E-2 (adaptada)", "Una pdf conjunta muestra DOS manchas separadas sobre una diagonal ascendente. ¿X e Y parecen independientes?", ["Sí, porque hay dos manchas", "No: conocer X cambia dónde es probable encontrar Y", "Sí, todas las pdf conjuntas son independientes", "No se puede porque la pdf puede ser mayor que 1"], 1, "Si una mancha está abajo a la izquierda y la otra arriba a la derecha, X grande suele ir con Y grande: saber X aporta información sobre Y. Una pdf factorizable p(x,y)=p(x)p(y) no muestra esa dependencia diagonal. Es la idea de E-2 sin depender de su figura."],
  ["Extra", "Localización", "Teoría", "T-23 (reconstruida)", "Sobre ajustar una pose con mínimos cuadrados a marcas del mapa, ¿qué es correcto?", ["Necesita predicción de movimiento en cada iteración", "Puede usar solo observaciones y mapa, sin modelo de movimiento", "Puede ponderar residuos por incertidumbre de las medidas", "Necesita remuestreo de partículas"], [1, 2], "El ajuste geométrico compara lo observado con las marcas del mapa y minimiza residuos; puede dar más peso a medidas fiables. Una pose odométrica puede servir de PUNTO INICIAL, pero el ajuste no incorpora por ello una etapa obligatoria de predicción de movimiento. No usa partículas."],
  ["Extra", "Localización", "Práctica", "P-5 (adaptada)", "En una localización iterativa con medidas y mapa, ¿qué orden conceptual tiene sentido?", ["Pose inicial → predecir medidas → calcular residuos/jacobiano → actualizar pose → repetir", "Actualizar pose antes de tener pose inicial", "Remuestrear antes de leer medidas y sin partículas", "Descartar todas las marcas y ajustar solo la velocidad"], 0, "Paso 1: necesitas una estimación inicial de la pose. Paso 2: con esa pose predices lo que debería ver el sensor. Paso 3: comparas predicción con datos reales para formar residuos y calculas derivadas (jacobiano). Paso 4: obtienes la corrección de pose y repites hasta converger. El documento P-5 original no conserva el código completo, por eso aquí se pregunta solo el orden conceptual."],
  ["L2", "MVSim", "Práctica", "Práctica 2.1", "En el archivo de mundo de MVSim, ¿qué hace default_sensors=false en el vehículo?", ["Desactiva sensores predeterminados de la clase para poder elegir solo los necesarios", "Elimina el robot completo de la simulación", "Convierte el LiDAR en una cámara", "Obliga a usar /odom como verdad global"], 0, "Paso 1: el mundo coloca una instancia de una clase de vehículo; la clase puede traer sensores por defecto. Paso 2: default_sensors=false evita cargar esos sensores pesados. Paso 3: puedes añadir explícitamente solo el LiDAR 2D al vehículo. No borra el chasis ni sus órdenes de velocidad."],
  ["L2", "MVSim", "Teoría", "Práctica 2.1", "¿Qué diferencia hay entre /tf y /tf_static en ROS 2?", ["/tf publica transformaciones que cambian, /tf_static relaciones fijas", "Las dos transportan órdenes Twist", "Solo /tf_static sirve para mover ruedas", "La primera es siempre ground truth"], 0, "En la cadena map → odom → base_link → sensores, la pose del cuerpo respecto a odom cambia al moverse y se publica dinámicamente. La posición de un sensor rígidamente sujeto al robot suele ser estática respecto a base_link. RViz2 necesita ambas para colocar lecturas."],
  ["L3", "Código de prácticas", "Práctica", "Práctica 3.1 / N-50", "En el cuadrado de 8×8 m avanzas 2 m por paso, girando 90° a la derecha al acabar cada lado. ¿Cuántos pasos cierran el recorrido?", ["4", "12", "15", "16"], 3, "Paso 1: un lado mide 8 m y cada avance mide 2 m, por tanto 8/2=4 pasos por lado. Paso 2: hay 4 lados: 4×4=16 avances. Paso 3: con 15 pasos falta el último avance; partiendo de (0,0) hacia el norte, se queda en (2,0), mirando al oeste antes del paso 16. Si una figura muestra 16 poses, puede contar la inicial más 15 avances."],
  ["L3", "Código de prácticas", "Práctica", "Práctica 3.1", "En tcomp(pose, [2,0,−π/2]), ¿con qué orientación se transforma el avance de 2 m?", ["Con la orientación anterior; después se actualiza el giro final", "Con la orientación nueva antes de avanzar", "Con el promedio de ambas siempre", "No hay que rotar: 2 m son x global"], 0, "Paso 1: el segundo argumento es un incremento LOCAL. Paso 2: la composición rota (2,0) con θ de pose, es decir, con la orientación inicial. Paso 3: la orientación final vale θ−π/2. Ojo: esto NO equivale a mandar simultáneamente velocidad y giro durante todo el paso; ese movimiento seguiría un arco."],
  ["L3", "Código de prácticas", "Teoría", "Práctica 3.2", "¿Por qué el modelo de arco con v y ω constantes es más exacto que actualizar siempre x+=vΔt cosθ, y+=vΔt senθ?", ["Integra el arco dentro del intervalo; Euler avanza recto y gira al final", "Porque nunca usa trigonometría", "Porque elimina el error de ruedas reales", "Porque el método Euler conoce el mapa"], 0, "El método exacto integra cómo θ cambia durante Δt y calcula el punto final del arco. Euler utiliza θ inicial durante todo el avance, sustituyendo ese arco por una tangente. Si ω≠0, Euler comete error de discretización; el modelo de arco es exacto solo bajo su hipótesis de velocidades constantes y ejecución ideal."],
  ["L3", "Código de prácticas", "Teoría", "Práctica 3.2", "El código pregunta if ω==0. ¿Qué otro problema puede aparecer con ω muy pequeño pero no nulo?", ["Cancelar números casi iguales al calcular el arco y perder precisión", "Volver al robot holonómico", "Cambiar de metros a milímetros automáticamente", "Que seno y coseno no admiten radianes"], 0, "Cuando ω es diminuto, R=v/ω es enorme. La fórmula global resta términos grandes casi iguales, por ejemplo R·sen(θ+ωΔt)−R·senθ: los decimales útiles se pierden. La práctica propone tratar |ω| pequeño con un umbral o emplear una fórmula estable; comparar solo con cero exacto no basta."],
  ["L3", "Código de prácticas", "Práctica", "Práctica 3.2", "En next_pose, ¿por qué np.sqrt(cov) @ randn(2,1) solo es adecuado si cov es diagonal?", ["Porque np.sqrt opera elemento a elemento y no calcula la raíz matricial general", "Porque randn solo genera un escalar", "Porque cualquier covarianza tiene dos filas iguales", "Porque el ruido gaussiano no admite correlación"], 0, "Paso 1: randn(2,1) tiene covarianza identidad. Paso 2: para obtener la deseada, multiplica por una matriz L tal que LLᵀ=cov. Paso 3: np.sqrt(cov) calcula la raíz de CADA ENTRADA, no garantiza LLᵀ=cov si hay covarianza cruzada. Paso 4: para una covarianza correlacionada y definida positiva, usa Cholesky o un generador normal multivariante."],
  ["L3", "Código de prácticas", "Práctica", "Práctica 3.2", "En next_pose se usa u += ruido. Si se reutiliza el mismo array u, ¿qué riesgo hay?", ["La orden original queda modificada in situ y acumula perturbaciones", "Se crea siempre una copia intacta", "La pose se convierte en escalar", "El ruido cambia mágicamente de media"], 0, "Paso 1: += sobre un array NumPy modifica el objeto recibido. Paso 2: si otro trozo de código conserva una referencia al mismo u, ahora ve la orden ruidosa, no la nominal. Paso 3: reutilizarla en el siguiente paso puede arrastrar ese ruido. Crea una copia antes de perturbar cuando quieras conservar la orden original."],
  ["L3", "Muestras", "Teoría", "Práctica 3.3", "En el modelo de odometría con ruido α, ¿qué parámetro produce error de ORIENTACIÓN al AVANZAR recto?", ["α₀", "α₁", "α₂", "α₃"], 1, "La práctica define Var(θ₁)=α₀θ₁²+α₁d²: al avanzar recto, d>0 y θ₁≈0, por lo que α₁ controla cuánto tuerce el robot durante el avance. α₀ relaciona giro con error angular; α₂ avance con error de distancia; α₃ giro con error de distancia."],
  ["L3", "Muestras", "Práctica", "Práctica 3.3", "Solo hay ruido de distancia σ_d; el giro inicial es prácticamente exacto. ¿Qué forma tendrá la nube de poses?", ["Alargada a lo largo del avance", "Un arco lateral pronunciado", "Un círculo perfecto centrado en el origen", "Una sola pose sin dispersión"], 0, "Paso 1: todos los robots orientan casi igual su avance. Paso 2: cada muestra recorre una distancia ligeramente distinta. Paso 3: sus destinos se sitúan sobre la misma dirección, unos más cerca y otros más lejos. Si lo ruidoso fuera θ₁, se abrirían en abanico y podría salir una banana."],
  ["L3", "Muestras", "Práctica", "Práctica 3.3", "La pose inicial es exacta; si multiplicas por 4 la covarianza Q del movimiento en todos los pasos, ¿qué pasa aproximadamente con las desviaciones típicas finales?", ["Se duplican", "Se multiplican por 4", "Se dividen por 2", "No cambian"], 0, "Paso 1: con pose inicial exacta, la covarianza acumulada es proporcional a Q en la propagación linealizada. Paso 2: si Q se multiplica por 4, las VARIANZAS finales se multiplican por 4. Paso 3: desviación típica = raíz cuadrada de varianza → √4=2. La elipse se ensancha por 2 en escala, no por 4."],
  ["L3", "Muestras", "Teoría", "Práctica 3.3", "¿Por qué cada partícula usa SU orientación anterior al aplicar giro–avance–giro?", ["Porque cada partícula representa una pose posible diferente y debe avanzar desde ella", "Porque todas las partículas comparten siempre exactamente la misma pose", "Porque se suma el incremento en ejes globales sin rotar", "Porque el encoder mide la verdad absoluta"], 0, "Si dos partículas miran en direcciones distintas, el mismo avance local las llevará a puntos globales diferentes. Usar la pose media para mover a todas borra esta diferencia y la nube deja de representar correctamente la incertidumbre; en particular se pierde la curvatura tipo banana."],
  ["L3", "Muestras", "Práctica", "Práctica 3.3", "Una función de muestreo recibe VARIANZA b²; scipy.stats.norm espera scale. ¿Qué valor pasas a scale?", ["√(b²), la desviación típica", "b² directamente", "(b²)²", "0 siempre"], 0, "Paso 1: el segundo parámetro del modelo, b², es una varianza. Paso 2: scipy.stats.norm(scale=...) espera DESVIACIÓN típica. Paso 3: convierte con raíz cuadrada: scale=√(b²). Por ejemplo, varianza 0,04 → scale=0,2. Si pasas 0,04, las muestras se dispersan cinco veces menos de lo esperado."],
].map(([lesson, topic, kind, source, prompt, options, answer, explanation], index) => ({
  id: `q${index + 1}`, lesson, topic, kind, source, prompt, options,
  answer: Array.isArray(answer) ? answer : [answer], explanation
}));

const lessonNames = { L1: "L1 · Introducción", L2: "L2 · Arquitecturas y ROS 2", L3: "L3 · Movimiento", Extra: "Ampliación · otros temas" };
const storageKey = "robotica-practica-parcial1-v1";
let progress = {};
try {
  const saved = JSON.parse(localStorage.getItem(storageKey) || "{}");
  progress = saved && typeof saved === "object" && !Array.isArray(saved) ? saved : {};
} catch { progress = {}; }
let session = [];
let responses = {};
let current = 0;

const $ = (selector) => document.querySelector(selector);
const filters = { lesson: $("#lesson-filter"), kind: $("#kind-filter"), source: $("#source-filter"), mode: $("#mode-filter") };
const query = new URLSearchParams(window.location.search);
for (const name of ["lesson", "kind"]) {
  const value = query.get(name);
  if (value && [...filters[name].options].some((option) => option.value === value)) filters[name].value = value;
}
const shuffle = (items) => {
  const copy = [...items];
  for (let i = copy.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [copy[i], copy[j]] = [copy[j], copy[i]];
  }
  return copy;
};

function updateStats() {
  const core = questions.filter((q) => q.lesson !== "Extra");
  const seen = core.filter((q) => progress[q.id]?.tries).length;
  const mastered = core.filter((q) => progress[q.id]?.lastCorrect).length;
  $("#bank-size").textContent = String(core.length);
  $("#done-count").textContent = `${seen} / ${core.length}`;
  $("#mastered-count").textContent = `${mastered} / ${core.length}`;
  $("#progress-fill").style.width = `${(mastered / core.length) * 100}%`;
  for (const lesson of ["L1", "L2", "L3", "Extra"]) {
    const el = $(`#count-${lesson}`);
    if (!el) continue;
    const items = questions.filter((q) => q.lesson === lesson);
    const masteredCount = items.filter((q) => progress[q.id]?.lastCorrect).length;
    el.textContent = `${masteredCount}/${items.length} dominadas`;
  }
  updateAvailable();
}

function availableQuestions() {
  return questions.filter((q) => {
    if (filters.lesson.value === "core" && q.lesson === "Extra") return false;
    if (filters.lesson.value !== "core" && filters.lesson.value !== "all" && q.lesson !== filters.lesson.value) return false;
    if (filters.kind.value !== "all" && q.kind !== filters.kind.value) return false;
    if (filters.source.value === "past" && !/^(E-|T-|P-)/.test(q.source)) return false;
    if (filters.source.value === "bank" && !/^N-/.test(q.source)) return false;
    if (filters.source.value === "new" && q.source !== "Nueva" && !q.source.startsWith("Práctica ")) return false;
    if (filters.mode.value === "wrong" && (!progress[q.id]?.tries || progress[q.id]?.lastCorrect)) return false;
    if (filters.mode.value === "unseen" && progress[q.id]?.tries) return false;
    return true;
  });
}

function updateAvailable() {
  $("#available").textContent = `${availableQuestions().length} preguntas disponibles con estos filtros`;
}

function buildSession() {
  const pool = availableQuestions();
  if (!pool.length) {
    $("#filter-error").textContent = "No hay preguntas con esos filtros. Prueba a cambiar la lección, el origen o el modo.";
    return;
  }
  $("#filter-error").textContent = "";
  const mode = $("#session-size").value;
  if (mode === "all" || pool.length <= 20) {
    session = shuffle(pool);
  } else {
    const target = { L1: 4, L2: 6, L3: 10, Extra: filters.lesson.value === "all" ? 0 : 20 };
    const taken = new Set();
    for (const lesson of ["L1", "L2", "L3", "Extra"]) {
      const subset = shuffle(pool.filter((q) => q.lesson === lesson)).slice(0, target[lesson]);
      subset.forEach((q) => taken.add(q));
    }
    session = shuffle([...taken, ...shuffle(pool.filter((q) => !taken.has(q))).slice(0, 20 - taken.size)]);
  }
  responses = {};
  current = 0;
  $("#quiz").hidden = false;
  $("#result").hidden = true;
  showQuestion();
  $("#quiz").scrollIntoView({ behavior: "smooth", block: "start" });
}

function addText(tag, text, className) {
  const element = document.createElement(tag);
  element.textContent = text;
  if (className) element.className = className;
  return element;
}

function showQuestion() {
  if (current >= session.length) {
    showResult();
    return;
  }
  const q = session[current];
  const saved = responses[q.id];
  $("#choice-error").textContent = "";
  $("#question-number").textContent = `Pregunta ${current + 1} de ${session.length}`;
  $("#quiz-progress").style.width = `${((current + 1) / session.length) * 100}%`;
  $("#question-meta").textContent = `${lessonNames[q.lesson]} · ${q.topic} · ${q.kind} · ${q.source}${q.source.startsWith("T-") || q.source.startsWith("P-") ? " (reconstruida/adaptada cuando se indica)" : ""}`;
  $("#question-title").textContent = q.prompt;
  $("#answer-hint").textContent = q.answer.length > 1 ? "Marca todas las respuestas correctas." : "Elige una respuesta.";
  const options = $("#options");
  options.replaceChildren();
  q.options.forEach((option, index) => {
    const label = document.createElement("label");
    label.className = "option";
    const input = document.createElement("input");
    input.type = q.answer.length > 1 ? "checkbox" : "radio";
    input.name = "choice";
    input.value = String(index);
    input.checked = !!saved?.selected.includes(index);
    input.disabled = !!saved;
    const letter = addText("span", `${String.fromCharCode(65 + index)}.`, "option-letter");
    label.append(input, letter, addText("span", option));
    if (saved) {
      if (q.answer.includes(index)) label.classList.add("correct-option");
      else if (saved.selected.includes(index)) label.classList.add("wrong-option");
    }
    options.append(label);
  });
  const feedback = $("#feedback");
  feedback.hidden = !saved;
  feedback.replaceChildren();
  if (saved) {
    feedback.className = saved.correct ? "feedback is-correct" : "feedback is-wrong";
    feedback.append(addText("h3", saved.correct ? "Correcto. Así se razona:" : "Todavía no. Vamos paso a paso:"));
    if (!saved.correct) feedback.append(addText("p", `Respuesta correcta: ${q.answer.map((i) => String.fromCharCode(65 + i)).join(", ")}.`, "right-answer"));
    feedback.append(addText("p", q.explanation, "explanation"));
  }
  $("#check-button").hidden = !!saved;
  $("#next-button").hidden = !saved;
  $("#next-button").textContent = current === session.length - 1 ? "Ver resultados" : "Siguiente →";
  $("#prev-button").disabled = current === 0;
  $("#score-line").textContent = `${Object.keys(responses).length}/${session.length} respondidas · ${Object.values(responses).filter((r) => r.correct).length} correctas`;
}

function checkAnswer() {
  const q = session[current];
  if (responses[q.id]) return;
  const selected = [...document.querySelectorAll("#options input:checked")].map((input) => Number(input.value));
  if (!selected.length) {
    $("#choice-error").textContent = "Selecciona al menos una opción antes de corregir.";
    return;
  }
  $("#choice-error").textContent = "";
  const correct = selected.length === q.answer.length && selected.every((index) => q.answer.includes(index));
  responses[q.id] = { selected, correct };
  const previous = progress[q.id] || { tries: 0 };
  progress[q.id] = { tries: previous.tries + 1, lastCorrect: correct };
  try { localStorage.setItem(storageKey, JSON.stringify(progress)); } catch {}
  updateStats();
  showQuestion();
  $("#feedback").scrollIntoView({ behavior: "smooth", block: "nearest" });
}

function showResult() {
  $("#quiz").hidden = true;
  $("#result").hidden = false;
  const right = Object.values(responses).filter((r) => r.correct).length;
  const wrong = session.length - right;
  $("#result-title").textContent = `Has acertado ${right} de ${session.length}`;
  $("#result-text").textContent = wrong
    ? `Has fallado ${wrong}. Puedes repetir solo los fallos de esta sesión o elegir «Falladas» en los filtros para repasar tus errores acumulados.`
    : "¡Todas correctas! Cambia los filtros para practicar otro bloque o haz un simulacro nuevo.";
  $("#repeat-button").hidden = !wrong;
  $("#result").scrollIntoView({ behavior: "smooth", block: "start" });
}

$("#start-button").addEventListener("click", buildSession);
$("#check-button").addEventListener("click", checkAnswer);
$("#next-button").addEventListener("click", () => {
  current++;
  showQuestion();
  if (current < session.length) $("#quiz").scrollIntoView({ behavior: "smooth", block: "start" });
});
$("#prev-button").addEventListener("click", () => { current--; showQuestion(); });
$("#exit-button").addEventListener("click", () => { $("#quiz").hidden = true; $("#filters").scrollIntoView({ behavior: "smooth" }); });
$("#repeat-button").addEventListener("click", () => {
  session = shuffle(session.filter((q) => !responses[q.id]?.correct));
  responses = {};
  current = 0;
  $("#result").hidden = true;
  $("#quiz").hidden = false;
  showQuestion();
  $("#quiz").scrollIntoView({ behavior: "smooth", block: "start" });
});
$("#new-button").addEventListener("click", buildSession);
Object.values(filters).forEach((element) => element.addEventListener("change", updateAvailable));
updateStats();
